    <script>
        var tableDataRaw = `{{GET_ALL_TABLES_JSON}}`; // Treat macro as string initially
        var tableData = {}; // Initialize as empty object
        var mapData = null, selectedMain = null, selectedSub = null;
        var protagonistCanMove = true; // Default assumption: protagonist can move

        try {
            // Attempt to parse the JSON string from the macro
            tableData = JSON.parse(tableDataRaw);
        } catch (e) {
             console.error("Error parsing tableData JSON:", e);
             console.error("Raw tableData string:", tableDataRaw);
             // Handle error state - maybe show an error message in the UI
             // For now, we'll let processJsonData handle the empty tableData object
        }

        function processJsonData(json) {
            var tablesByName = {};
            // Basic check if json is valid
            if (!json || typeof json !== 'object') {
                 console.error("Invalid JSON data received:", json);
                 return { title: '错误', time: '无法加载数据', locations: [], importantCharacters: [], externalAreas: [], currentUserPosition: {x: 400, y: 300}, shop: [], inventory: [], tasks: [] };
            }

            // Extract tables by name, assuming structure like {"sheet_ID": {name: "Table Name", content: [...]}}
            for (var sheetId in json) {
                if (Object.prototype.hasOwnProperty.call(json, sheetId) && json[sheetId] && json[sheetId].name && json[sheetId].content) { 
                    tablesByName[json[sheetId].name] = json[sheetId];
                }
            }

            var data = { title: '', time: '', locations: [], importantCharacters: [], externalAreas: [], currentUserPosition: {}, skills: [], inventory: [], tasks: [] };

            // --- Global Data --- (Indices from 1)
            var globalTable = tablesByName['全局数据表'];
            if (globalTable && globalTable.content && globalTable.content.length > 1 && globalTable.content[1]) {
                var global = globalTable.content[1];
                data.title = global[1] || '未知地图'; // Col 1
                data.time = global[2] || '未知时间'; // Col 2
                data.externalAreas = (global[3] || '').split(';').map(function(s) { return s.trim(); }).filter(Boolean); // Col 3
            } else {
                console.warn("Global data table missing or invalid.");
                data.title = '错误'; data.time = '无法加载全局数据';
            }

            // --- Protagonist --- (Two tables now)
            var protagonistInfoTable = tablesByName['主角信息'];
            var protagonistStatusTable = tablesByName['主角状态'];
            var protagonistData = { isProtagonist: true, name: '主角', details: { attributes: {} }, interactions: [] };

            if (protagonistInfoTable && protagonistInfoTable.content && protagonistInfoTable.content.length > 1 && protagonistInfoTable.content[1]) {
                var pInfo = protagonistInfoTable.content[1];
                // Indices: 1:名称, 2:性别/年龄, 3:外貌, 4:职业/身份, 5:背景, 6:性格
                protagonistData.name = pInfo[1] || '主角';
                protagonistData.genderAge = pInfo[2];
                protagonistData.appearance = pInfo[3];
                protagonistData.profession = pInfo[4];
                protagonistData.details.backstory = pInfo[5];
                protagonistData.details.personality = pInfo[6];
            } else {
                console.warn("Protagonist Info table missing or invalid.");
                protagonistData.name = '主角 (信息数据错误)';
            }

            if (protagonistStatusTable && protagonistStatusTable.content && protagonistStatusTable.content.length > 1 && protagonistStatusTable.content[1]) {
                var pStatus = protagonistStatusTable.content[1];
                // Indices: 1:状态, 2:移动, 3:金钱, 4:主地点, 5:次地点, 6:X, 7:Y, 8-13:六维, 14-17:互动
                protagonistData.details.status = pStatus[1];
                protagonistData.details.canMove = pStatus[2];
                protagonistData.details.money = pStatus[3];
                protagonistCanMove = !(pStatus[2] && pStatus[2].trim().toLowerCase() === '否');

                var posX = parseInt(pStatus[6]);
                var posY = parseInt(pStatus[7]);
                data.currentUserPosition = { x: !isNaN(posX) ? posX : 400, y: !isNaN(posY) ? posY : 300 };

                protagonistData.details.attributes = {
                    strength: pStatus[8],
                    intelligence: pStatus[9],
                    dexterity: pStatus[10],
                    constitution: pStatus[11],
                    charisma: pStatus[12],
                    perception: pStatus[13]
                };
                protagonistData.interactions = [pStatus[14], pStatus[15], pStatus[16], pStatus[17]].filter(Boolean);
            } else {
                console.warn("Protagonist Status table missing or invalid.");
                protagonistData.name = '主角 (状态数据错误)';
                data.currentUserPosition = {x: 400, y: 300};
            }
            data.importantCharacters.push(protagonistData);

            // --- Important Characters --- (Indices are 1-based)
            var importantCharsTable = tablesByName['重要人物表'];
            if (importantCharsTable && importantCharsTable.content) {
                importantCharsTable.content.slice(1).forEach(function(row) { 
                    if (!row || !row[1]) return; 

                    // Correct indices based on table_data.json: 1:姓名, 2:性别/年龄, 3:外貌, 4:职业, 5:性格, 6:背景, 7:关系, 8:状态, 9:物品, 10:能力, 11:好感度, 12:想法, 13-16:互动, 17:是否离场, 18:离场轮数, 19:剧情关键角色
                    var charData = { 
                        name: row[1], // Col 1
                        genderAge: row[2], // Col 2
                        appearance: row[3], // Col 3
                        profession: row[4], // Col 4
                        personality: row[5], // Col 5
                        backstory: row[6], // Col 6
                        relationship: row[7], // Col 7
                        status: row[8], // Col 8
                        items: row[9], // Col 9
                        abilities: row[10], // Col 10
                        affinity: row[11], // Col 11
                        thoughts: row[12], // Col 12
                        description: "状态: " + (row[8] || '未知') + " | 关系: " + (row[7] || '未知'), // Cols 8, 7
                        interactions: [row[13], row[14], row[15], row[16]].filter(Boolean), // Cols 13-16
                        isAway: row.length > 17 ? row[17] : undefined, // Col 17
                        awayTurns: row.length > 18 ? row[18] : undefined, // Col 18
                        isPlotCritical: row.length > 19 ? row[19] : undefined // Col 19
                     };

                     data.importantCharacters.push(charData); 
                });
            }

            // --- Skills --- (Indices are 1-based, from '主角技能表')
            var skillsTable = tablesByName['主角技能表'];
            data.skills = []; // Ensure skills array exists
            if (skillsTable && skillsTable.content) {
                skillsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1]) return; // Skip if row is invalid or name (col 1) missing
                    data.skills.push({
                        name: row[1], // Col 1: 技能名称
                        effect: row[2], // Col 2: 技能效果
                        level: row[3], // Col 3: 技能等级
                        mastery: row[4] // Col 4: 技能熟练度
                    });
                });
            }

            // --- Inventory --- (Indices are 1-based)
            var inventoryTable = tablesByName['背包物品表'];
            if (inventoryTable && inventoryTable.content) {
                inventoryTable.content.slice(1).forEach(function(row) {
                     if (!row || !row[1]) return; 
                    // Correct indices based on table_data.json: 1:名称, 3:描述
                    data.inventory.push({ 
                        name: row[1], // Col 1
                        description: row[3] // Col 3 
                    });
                });
            }

            // --- Sub Locations --- (Indices are 1-based)
            var subLocationsMap = new Map();
            var subLocationsTable = tablesByName['次级地点表'];
            if (subLocationsTable && subLocationsTable.content) {
                subLocationsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1] || !row[2]) return; 
                    // Correct indices based on table_data.json: 1:次级名称, 2:所属主地点, 3:环境描述
                    var subName = row[1], mainName = row[2], subDesc = row[3] || ''; 
                    if (!subLocationsMap.has(mainName)) subLocationsMap.set(mainName, []);
                    subLocationsMap.get(mainName).push({ name: subName, description: subDesc, elements: [] }); 
                });
            }

            // --- Map Elements --- (Indices are 1-based)
            var elementsTable = tablesByName['地图元素表'];
            if (elementsTable && elementsTable.content) {
                elementsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1] || !row[4]) return; 
                    // Correct indices based on table_data.json: 1:名称, 2:类型, 3:描述, 4:所属次级地点, 5:状态, 6:要求, 7-10:互动
                    var element = { 
                        name: row[1], // Col 1
                        type: row[2] || '未知', // Col 2
                        description: row[3] || '', // Col 3
                        status: row[5] || '未知', // Col 5
                        requirements: row[6] || '无', // Col 6
                        interactions: [row[7], row[8], row[9], row[10]].filter(Boolean) // Col 7-10
                    };
                    var subLocationName = row[4]; // Col 4
                    var found = false;
                    var mainLocIter = subLocationsMap.values();
                    var mainLocSubs;
                    while (!found && !(mainLocSubs = mainLocIter.next()).done) {
                         var sub = mainLocSubs.value.find(function(s) { return s.name === subLocationName; });
                         if (sub) {
                            sub.elements.push(element);
                            found = true;
                         }
                    }
                    if (!found) { console.warn("Element '" + element.name + "' assigned to non-existent sub-location '" + subLocationName + "'"); }
                });
            }

            // --- Tasks --- (Indices are 1-based)
            var tasksTable = tablesByName['任务与事件表'];
             if (tasksTable && tasksTable.content) {
                 tasksTable.content.slice(1).forEach(function(row) {
                     if (!row || !row[1]) return; // Skip if row invalid or name (col 1) missing
                     data.tasks.push({ 
                         name: row[1], // Col 1: 任务名称
                         description: row[2], // Col 2: 任务描述
                         publisher: row[3], // Col 3: 发布者
                         keyInfo: row[4], // Col 4: 任务关键信息
                         progress: row[5], // Col 5: 任务进度
                         timeLimit: row[6], // Col 6: 任务时限
                         reward: row[7] // Col 7: 任务奖励
                     });
                 });
             }

            // --- Main Locations --- (Indices are 1-based)
            var mainLocationsTable = tablesByName['主要地点表'];
            if (mainLocationsTable && mainLocationsTable.content) {
                 mainLocationsTable.content.slice(1).forEach(function(row) {
                     if (!row) return; 
                     // Correct indices based on table_data.json: 1:名称, 2:X, 3:Y, 4:宽, 5:高, 6:类型, 7:描述, 8:区域
                     var name = row[1] || '未命名地点'; // Col 1
                     var x = parseInt(row[2]); var y = parseInt(row[3]); // Col 2, Col 3
                     var width = parseInt(row[4]); var height = parseInt(row[5]); // Col 4, Col 5

                     if (name && !isNaN(x) && !isNaN(y) && !isNaN(width) && width > 0 && !isNaN(height) && height > 0) {
                         data.locations.push({ 
                             name: name, x: x, y: y, width: width, height: height, 
                             type: row[6] || '未知', // Col 6
                             description: row[7] || '', // Col 7
                             region: row[8] || '未知', // Col 8
                             subLocations: subLocationsMap.get(name) || []
                         });
                     } else {
                         console.warn("Skipping invalid/incomplete location data:", row);
                     }
                 });
             } else {
                  console.warn("Main locations table missing or invalid.");
             }

            return data;
        }

        function renderMapInterface(data) {
            document.getElementById('map-title').textContent = data.title;
            document.getElementById('map-time').textContent = data.time;
            var svg = document.getElementById('visual-map'), ns = "http://www.w3.org/2000/svg";
            svg.innerHTML = ''; // Clear previous map

            if (!data || !data.locations || !Array.isArray(data.locations)) {
                console.error("Cannot render map: Invalid locations data.");
                return;
            }

            data.locations.forEach(function(l) {
                 // Double check location properties needed for rendering
                 if (typeof l.x !== 'number' || typeof l.y !== 'number' || typeof l.width !== 'number' || l.width <= 0 || typeof l.height !== 'number' || l.height <= 0 || !l.name) {
                     console.warn("Skipping rendering invalid location:", l);
                     return;
                 }

                var g = document.createElementNS(ns, 'g');
                g.setAttribute('transform', 'translate(' + l.x + ', ' + l.y + ')');
                g.classList.add('map-location-group');
                g.dataset.location = l.name;
                g.addEventListener('click', function() { selectMainLocation(l); });
                var r = document.createElementNS(ns, 'rect');
                r.setAttribute('width', l.width);
                r.setAttribute('height', l.height);
                r.classList.add('map-location-rect');
                var t = document.createElementNS(ns, 'text');
                t.setAttribute('x', l.width / 2);
                t.setAttribute('y', l.height / 2);
                t.classList.add('map-location-label');
                t.textContent = l.name;
                g.appendChild(r);
                g.appendChild(t);
                svg.appendChild(g);
            });

            // Render player position dot if valid
             if (data.currentUserPosition && typeof data.currentUserPosition.x === 'number' && typeof data.currentUserPosition.y === 'number') {
                var dot = document.createElementNS(ns, 'circle');
                dot.setAttribute('cx', data.currentUserPosition.x);
                dot.setAttribute('cy', data.currentUserPosition.y);
                dot.setAttribute('r', 5);
                dot.setAttribute('fill', 'red');
                svg.appendChild(dot);
            }
        }

