        // Helper function to show a custom alert
        function showCustomAlert(message) {
            var modal = document.getElementById('alert-modal');
            var textElement = document.getElementById('alert-modal-text');
            var okBtn = document.getElementById('alert-modal-ok-btn');

            textElement.textContent = message;
            modal.classList.remove('hidden');

            var newOkBtn = okBtn.cloneNode(true);
            okBtn.parentNode.replaceChild(newOkBtn, okBtn);

            newOkBtn.addEventListener('click', function() {
                modal.classList.add('hidden');
            });
        }

        // Helper function to show a custom confirmation dialog
        function showCustomConfirm(actionDescription, onConfirm) {
            var modal = document.getElementById('confirm-modal');
            var textElement = document.getElementById('confirm-modal-text');
            var confirmBtn = document.getElementById('confirm-modal-confirm-btn');
            var cancelBtn = document.getElementById('confirm-modal-cancel-btn');

            textElement.textContent = "是否确认执行以下操作？\n\n" + actionDescription;
            modal.classList.remove('hidden');

            // Replace buttons with clones to remove all prior event listeners
            var newConfirmBtn = confirmBtn.cloneNode(true);
            confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);

            var newCancelBtn = cancelBtn.cloneNode(true);
            cancelBtn.parentNode.replaceChild(newCancelBtn, cancelBtn);

            newConfirmBtn.addEventListener('click', function() {
                modal.classList.add('hidden');
                if (typeof onConfirm === 'function') {
                    onConfirm();
                }
            });

            newCancelBtn.addEventListener('click', function() {
                modal.classList.add('hidden');
                console.log("User cancelled action: " + actionDescription);
            });
        }

        // Helper function to check if protagonist can move
        function checkMovementAllowed() {
            if (!protagonistCanMove) {
                showCustomAlert("你目前不能移动");
                return false;
            }
            return true;
        }

        function sendGameActionRequest(actionDescription, message, errorMessage) {
            if (errorMessage === undefined) {
                errorMessage = "操作失败";
            }

            showCustomConfirm(actionDescription, function() {
                console.log("Sending game action request:", message);
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash('/send ' + message + ' || /trigger');
                    } catch (e) {
                        console.error("Error sending game action request:", e);
                        showCustomAlert(errorMessage + '，请检查控制台信息或重试。');
                    }
                } else {
                    console.warn('triggerSlash function not found. Displaying alert instead.');
                    // This is a dev-only message, so a simple alert is fine here. Or use the custom one.
                    showCustomAlert('操作请求已生成 (仅供测试):\n' + message + '\n\n在实际环境中，这将自动发送。');
                }
            });
        }

