        function init() {
             try {
                 // Ensure tableData is somewhat valid before processing
                 if (typeof tableData !== 'object' || tableData === null) {
                      console.error("Initial tableData is invalid or null. Using default data.");
                      // Provide a minimal default structure if tableData is completely unusable
                      tableData = { "0": { name: "全局数据表", content: [["列标题"], ["默认地图", "初始时间"]] } }; 
                 }
                 mapData = processJsonData(tableData);

                 // Check if mapData processing resulted in usable data
                 if (!mapData) {
                     console.error("mapData processing failed. Cannot initialize UI.");
                     document.getElementById('map-title').textContent = "数据加载错误";
                     return; // Stop initialization
                 }

                 renderMapInterface(mapData);
                 updateImportantCharactersDisplay(mapData.importantCharacters);
                 renderExternalAreas(mapData.externalAreas);
                 displaySkillItems(mapData.skills); // Changed from shop to skills
                 displayInventoryItems(mapData.inventory);
                 displayTaskItems(mapData.tasks); 

                 // Setup event listeners
                 document.getElementById('close-modal-btn').addEventListener('click', function() { document.getElementById('character-modal').classList.add('hidden'); });
                 document.getElementById('skill-button').addEventListener('click', function() { document.getElementById('skill-modal').classList.remove('hidden'); });
                 document.getElementById('close-skill-btn').addEventListener('click', function() { document.getElementById('skill-modal').classList.add('hidden'); });
