        /* Top Row: Larger buttons with text */
        .bottom-function-bar {
          order: 1; /* First row */
          width: auto; /* Let it shrink to fit content */
          max-width: 100%; /* Ensure it doesn't exceed screen width */
          gap: 4px; /* Further reduced gap */
