        }
        .function-btn span:first-child {
          font-size: 12px; /* Further reduced icon size */
        }

        /* Bottom Row: Small icon-only buttons */
        .right-tool-bar {
          order: 2; /* Second row */
          width: auto; /* Let it shrink to fit content */
          max-width: 100%;
          justify-content: center;
          margin-top: 0;
          gap: 4px; /* Further reduced gap */
          flex-wrap: nowrap; /* Prevent wrapping */
          flex-shrink: 1; /* Allow the bar to shrink */
        }
        .right-tool-bar > div {
          height: 30px;
          width: 32px;
          padding: 0; /* Remove padding for icon centering */
