        .sub-location-grid {
          grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
          gap: 8px;
        }

        /* --- Modals --- */
        .modal-content {
          margin-bottom: 15px; /* 优化1: 减少内容与按钮间的间距 */
        }
        .modal-dialog {
          width: 95%;
          max-height: 78vh; /* 再次修复：为移动端弹窗设置更安全的最大高度 */
