          font-size: 14px;
        }
        #modal-character-portrait {
          width: 90px;
          height: 90px;
        }
        .interaction-options-grid {
          /* 任务3：重新排布互动按钮，给信息窗口腾出空间 */
          grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
          gap: 8px;
        }
        .interaction-button {
          /* 任务3：降低互动按钮大小 */
          padding: 8px 6px;
          font-size: 13px;
        }
        .modal-dialog .interaction-options-grid {
            padding-top: 10px; /* 优化1: 减少互动按钮区域的顶部间距 */
        }

        /* 任务1: 将所有移动端模式下互动按钮UI栏的padding改为仅垂直生效，统一间距 */
        .content-pane[data-content='profile'] .profile-interactions,
