        }
        .maho-interface.fullscreen-active .right-tool-bar {
          gap: 4px; /* Further reduced gap */
        }

        /* 修复：明确控制移动端全屏模式下的弹窗高度 */
        .maho-interface.fullscreen-active .modal-dialog {
          max-height: 78vh;
        }

        /* 再次修复：为地图相关的弹窗明确设置最大高度，解决溢出问题 */
        #main-location-modal .modal-dialog,
        #sub-location-modal .modal-dialog,
        #map-element-modal .modal-dialog {
          max-height: 78vh;
        }

        /* --- 20250727 优化移动端样式 --- */

        /* 任务3：降低所有移动端模式下互动按钮与互动弹窗地大小 */
        .modal-dialog {
            padding: 15px;
        }
        .interaction-options-grid {
            grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
            gap: 8px;
        }
        .interaction-button {
            padding: 8px 6px;
            font-size: 13px;
        }

        /* 任务1：降低竖屏移动端全屏模式下，重要人物栏的宽度 */
        .maho-interface.fullscreen-active .maho-text-container {
            right: 18%;
        }
        .maho-interface.fullscreen-active .person-portrait {
            width: 45px;
            height: 45px;
        }
      }

      /* --- New Loading Spinner Styles --- */
      @keyframes spin {
        0% {
          transform: rotate(0deg);
        }
        100% {
          transform: rotate(360deg);
        }
      }
      .loading-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgb(16, 24, 40); /* Fallback/Default Opaque background */
        z-index: 5;
        display: none;
        justify-content: center;
        align-items: center;
        flex-direction: column;
        gap: 15px;
        color: #c0d0e0;
        font-family: 'Noto Serif SC', serif;
      }
      .loading-spinner {
        width: 40px;
        height: 40px;
        border: 4px solid rgba(100, 150, 200, 0.2);
        border-top-color: rgba(120, 180, 255, 0.8);
        border-radius: 50%;
        animation: spin 1s linear infinite;
      }
      .gal-loading-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgb(16, 24, 40);
        z-index: 999;
        display: none;
        justify-content: center;
        align-items: center;
        flex-direction: column;
        gap: 15px;
        color: #c0d0e0;
        font-family: 'Noto Serif SC', serif;
        border-radius: 8px;
      }


      /* --- Responsive Fullscreen Overrides (Mobile) --- */

      /* Fullscreen on Portrait Mobile (e.g. phone held vertically) */
      /* This refines the existing rules inside max-width: 600px */
      /* @media (max-width: 600px) {
        .maho-interface.fullscreen-active .maho-text-container {
          right: 5%;
          left: 5%;
        }
        .maho-interface.fullscreen-active .people-around-container {
          display: none;
        }
      } */

      /* Fullscreen on Landscape Mobile (e.g. phone held horizontally) */
      /* This is a new block to distinguish from Desktop Fullscreen by using aspect ratio. */
      @media (orientation: landscape) and (min-aspect-ratio: 19/10) {
        .maho-interface.fullscreen-active {
          font-size: 1em; /* Reset font size to be smaller than desktop */
        }
        .maho-interface.fullscreen-active .maho-text-container {
          font-size: 0.85em; /* 调小正文字体 */
          left: 15%; /* More horizontal space available */
          right: 15%;
        }
        .maho-interface.fullscreen-active .person-portrait {
          width: 75px; /* Smaller portraits */
          height: 75px;
        }
        .maho-interface.fullscreen-active .right-tool-bar {
          gap: 4px; /* Add this to reduce gap */
        }
        .maho-interface.fullscreen-active .function-btn,
        .maho-interface.fullscreen-active .right-tool-bar > div {
          /* 修复2：再次降低横屏全屏模式下按钮高度和字体，使其与顶部信息栏相似 */
          height: 28px; /* 大幅调低按钮高度 */
