        .maho-interface.fullscreen-active .top-info-bar {
          padding: 8px 15px;
          font-size: 0.9em;
        }
        .maho-interface.fullscreen-active .ui-section {
          /* 优化1: 减少横屏全屏时底部栏的垂直内边距 */
          padding-top: 2px;
          padding-bottom: 2px;
        }
        .maho-interface.fullscreen-active .bottom-function-bar {
            padding-top: 0;
            padding-bottom: 0;
        }

        /* 任务2: 优化横屏全屏下的主角面板，为信息栏腾出更多垂直空间 */
        .maho-interface.fullscreen-active .content-pane[data-content='profile'] .profile-top-section {
            margin-bottom: 5px; /* 减少下方间距 */
        }
        .maho-interface.fullscreen-active .content-pane[data-content='profile'] #profile-pane-portrait {
            width: 90px;  /* 缩小头像 */
            height: 90px;
        }
        .maho-interface.fullscreen-active .content-pane[data-content='profile'] .attributes-grid {
            padding: 5px 8px; /* 减少内边距 */
            gap: 2px 8px; /* 减少垂直间隙 */
        }
        .maho-interface.fullscreen-active .content-pane[data-content='profile'] .attribute-item .attr-value {
            font-size: 0.9em; /* 缩小属性字号 */
        }
      }
    </style>
