    <!-- Javascript remains the same as the target file -->
    <script>
      (function () {
        // --- SillyTavern Global API ---
        // These are provided by the SillyTavern environment at runtime.
        /* global TavernHelper, getChatMessages, getCurrentMessageId, triggerSlash */
        if (
          typeof TavernHelper === 'undefined' ||
          typeof getChatMessages === 'undefined' ||
          typeof getCurrentMessageId === 'undefined'
        ) {
          document.addEventListener('DOMContentLoaded', function () {
            document.body.innerHTML =
              '<div style="color:red; text-align:center; padding: 20px; font-family: sans-serif;">错误：SillyTavern API 未找到。此界面必须在 SillyTavern 环境中运行。</div>';
          });
          return; // Stop script execution
        }

        // --- UI Settings Management (using localStorage) ---

        /**
         * Applies a fallback UI (question mark on a solid color) to an image container.
         * @param {HTMLElement} element - The container element for the image.
         */
        function applyImageFallback(element) {
            if (!element) return;
            const colors = ['#5a5a5a', '#6a4c4c', '#4c6a4c', '#4c4c6a', '#6a6a4c', '#4c6a6a'];
            const randomColor = colors[Math.floor(Math.random() * colors.length)];

            element.innerHTML = ''; // Clear any broken img tags
            element.style.backgroundImage = 'none';
            element.style.backgroundColor = randomColor;
            element.style.display = 'flex';
            element.style.justifyContent = 'center';
            element.style.alignItems = 'center';
            element.style.color = '#fff';
            // Adjust font size relative to container size for better scaling
            const size = Math.min(element.offsetWidth, element.offsetHeight);
            element.style.fontSize = `${size * 0.6}px`;
            element.style.fontWeight = 'bold';
            element.style.lineHeight = '1';
            element.textContent = '?';
        }

        /**
         * Tries to load an avatar from multiple sources with a fallback mechanism.
         * @param {HTMLImageElement} imgElement - The <img> element to set the src for.
         * @param {HTMLElement} containerElement - The container div, for applying fallback UI.
         * @param {string} characterName - The name of the character, used for localStorage key.
         * @param {string} avatarFileName - The base name of the avatar file (without extension).
         */
        function findAndSetAvatar(imgElement, containerElement, characterName, avatarFileName) {
            const uiSettings = getUiSettings();
            const customAvatar = localStorage.getItem(`st-beautify-ui-avatar-${characterName}`);
            const defaultAvatarUrl = 'https://tc.z.wiki/autoupload/f/Mni8OcLITdv7Gy5JSasVq1jzZpLi8sXGZgGJW-1aOMmyl5f0KlZfm6UsKj-HyTuv/20250727/aU1g/566X575/QQ20250727-210210.png';
            const extensions = ['png', 'jpg', 'jpeg', 'gif', 'webp'];

            const sources = [];

            // 1. Add custom avatar from localStorage (highest priority)
            if (customAvatar) {
                sources.push(customAvatar);
            }

            // 2. Add file-based avatars if a filename is provided
            if (avatarFileName) {
                const pathsInOrder = uiSettings.useNetworkAssets
                    ? [config.networkCharacterImagePath, config.characterImagePath]
                    : [config.characterImagePath, config.networkCharacterImagePath];

                pathsInOrder.forEach(path => {
                    extensions.forEach(ext => {
                        const url = `${path}${avatarFileName}.${ext}`;
                        if (!sources.includes(url)) { // Prevent duplicates
                            sources.push(url);
                        }
                    });
                });
            }

            // 3. Add the final default avatar
            sources.push(defaultAvatarUrl);

            let sourceIndex = 0;
            const tryNext = () => {
                if (sourceIndex >= sources.length) {
                    applyImageFallback(containerElement);
                    return;
                }
                imgElement.src = sources[sourceIndex];
                sourceIndex++;
            };

            imgElement.onerror = tryNext;
            tryNext(); // Start the chain
        }

        /**
         * Retrieves UI settings from localStorage.
         * Provides default values if settings are not found.
         * @returns {{isZeroLayerMode: boolean, useNetworkAssets: boolean, enableGalLoading: boolean}}
         */
        function getUiSettings() {
            const settings = {
                // Default values. Note: The original logic defaulted to true if undefined.
                isZeroLayerMode: true,
                useNetworkAssets: true,
                enableGalLoading: true,
                typingSpeed: 2, // 新增：默认速度为“正常”
            };

            const zeroLayerStored = localStorage.getItem('st-beautify-ui-is_zero_layer_mode');
            if (zeroLayerStored !== null) {
                settings.isZeroLayerMode = zeroLayerStored === 'true';
            }

            const networkAssetsStored = localStorage.getItem('st-beautify-ui-use_network_assets');
            if (networkAssetsStored !== null) {
                settings.useNetworkAssets = networkAssetsStored === 'true';
            }

            const galLoadingStored = localStorage.getItem('st-beautify-ui-enable_gal_mode_loading');
            if (galLoadingStored !== null) {
                settings.enableGalLoading = galLoadingStored === 'true';
            }

            const typingSpeedStored = localStorage.getItem('st-beautify-ui-typing_speed');
            if (typingSpeedStored !== null) {
                settings.typingSpeed = parseInt(typingSpeedStored, 10);
            }

            return settings;
        }

        /**
         * Saves a specific UI setting to localStorage.
         * @param {string} key - The setting key to save.
         * @param {boolean} value - The boolean value to save.
         */
        function setUiSetting(key, value) {
            const validKeys = {
                'is_zero_layer_mode': 'st-beautify-ui-is_zero_layer_mode',
                'use_network_assets': 'st-beautify-ui-use_network_assets',
                'enable_gal_mode_loading': 'st-beautify-ui-enable_gal_mode_loading',
                'typing_speed': 'st-beautify-ui-typing_speed',
            };
            if (validKeys[key]) {
                localStorage.setItem(validKeys[key], String(value));
                console.log(`UI Setting saved: ${validKeys[key]} = ${value}`);
            }
        }


        // --- World Book Context Saving Counter ---
        let currentHistoryIndex = localStorage.getItem('st-beautify-ui-history-nav-index')
          ? parseInt(localStorage.getItem('st-beautify-ui-history-nav-index'), 10)
          : null;
        const NUM_LOREBOOK_ENTRIES = 5;
        // let lorebookSaveIndex = 1; // Removed: Now managed via persistent chat variables.

        /**
         * 将最近的5条聊天记录保存到与当前角色卡关联的世界书中的5个循环条目之一。
         * 条目名为 '上下文楼层_1' 到 '上下文楼层_5'。
         * 该函数会自动创建、启用这些条目，并将其设置为常量（蓝灯）。
         * The save index is persisted in chat variables to survive UI reloads.
         */
        async function saveContextToLorebook(customMessageList = null) {
          // Check if zero-layer mode is active. If not, do not auto-save.
          const uiSettings = getUiSettings();
          if (!uiSettings.isZeroLayerMode) {
            console.log('Zero-layer mode is disabled. Skipping auto-save.');
            return;
          }

          const LOREBOOK_KEY_PREFIX = '上下文楼层_';
          const TABLE_KEY_PREFIX = '表格数据_'; // 新增：表格数据条目的前缀
          const NUM_ENTRIES = 5;
          const MESSAGE_COUNT = 5; // 要保存的最近消息数量
          const INDEX_VAR_KEY = 'lorebook_context_save_index'; // Key for chat variable

          try {
            // A. Get the current save index from chat variables
            // Based on the surrounding code, we assume getVariables/replaceVariables are on TavernHelper.
            const chatVars = (await TavernHelper.getVariables({ type: 'chat' })) || {};
            let lorebookSaveIndex = chatVars[INDEX_VAR_KEY] || 1;
            if (typeof lorebookSaveIndex !== 'number' || lorebookSaveIndex < 1 || lorebookSaveIndex > NUM_ENTRIES) {
              lorebookSaveIndex = 1; // Sanitize the value in case of corruption
            }

            // 1. 动态获取角色卡绑定的世界书名称
            const LOREBOOK_NAME = await TavernHelper.getCurrentCharPrimaryLorebook();
            if (!LOREBOOK_NAME) {
              console.warn('当前角色未绑定主世界书，跳过上下文保存。');
              return;
