            // 2. 检查世界书本身是否存在
            const lorebooks = await TavernHelper.getLorebooks();
            if (!lorebooks.includes(LOREBOOK_NAME)) {
              console.error(`世界书 "${LOREBOOK_NAME}" 不存在。`);
              showCustomAlert(`错误：角色卡指定的世界书 "${LOREBOOK_NAME}" 未找到。`);
              return;
            }

            const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
            const currentContextKey = `${LOREBOOK_KEY_PREFIX}${lorebookSaveIndex}`;
            const currentTableKey = `${TABLE_KEY_PREFIX}${lorebookSaveIndex}`;

            let contextEntry = allEntries.find(entry => entry.comment === currentContextKey);
            let tableEntry = allEntries.find(entry => entry.comment === currentTableKey);

            // 封装一个创建或更新条目的函数，避免代码重复
            const createOrUpdateEntry = async (key, content, existingEntry) => {
              const entryType = key.startsWith(TABLE_KEY_PREFIX) ? 'selective' : 'constant';
              if (!existingEntry) {
                // Create new entry
                console.log(`在 "${LOREBOOK_NAME}" 中创建世界书条目: ${key}`);
                const newEntryData = {
                  comment: key,
                  keys: [key],
                  content: content,
                  enabled: true,
                  type: entryType,
                  position: 'after_char',
                  order: key.startsWith(LOREBOOK_KEY_PREFIX) ? 1000 + lorebookSaveIndex : 2000 + lorebookSaveIndex,
                };
                await TavernHelper.createLorebookEntries(LOREBOOK_NAME, [newEntryData]);
                const updatedEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
                return updatedEntries.find(entry => entry.comment === key);
              } else {
                // Update existing entry
                const updateEntryData = {
                  uid: existingEntry.uid,
                  content: content,
                  enabled: true,
                  type: entryType,
                };
                await TavernHelper.setLorebookEntries(LOREBOOK_NAME, [updateEntryData]);
                return existingEntry;
              }
            };

            // 1. 处理并保存上下文正文
            // [BUGFIX] If a custom message list is provided (from handleZeroLevelReply), use it.
            // Otherwise, fetch the default history. This solves the stale context issue.
            const allMessages = customMessageList || (await getChatMessages(getCurrentMessageId()));
            const recentMessages = allMessages.slice(-MESSAGE_COUNT);
            const contextContent = recentMessages
              .map(msg => {
                const role = msg.is_user ? 'USER' : 'CHARACTER';
                return `${role}: ${msg.message}`;
              })
              .join('\n---\n');

            await createOrUpdateEntry(currentContextKey, contextContent, contextEntry);
            console.log(`上下文已保存到 "${LOREBOOK_NAME}" 的条目: ${currentContextKey}`);

            // 2. 处理并保存表格数据
            const tableDataJson = parent.AutoCardUpdaterAPI.exportTableAsJson();
            const tableContent = JSON.stringify(tableDataJson, null, 2); // 格式化JSON以便阅读

            await createOrUpdateEntry(currentTableKey, tableContent, tableEntry);
            console.log(`表格数据已保存到 "${LOREBOOK_NAME}" 的条目: ${currentTableKey}`);

            // B. 循环到下一个索引 (1-5)
            const nextSaveIndex = (lorebookSaveIndex % NUM_ENTRIES) + 1;

            // C. Save the next index back to chat variables
            chatVars[INDEX_VAR_KEY] = nextSaveIndex;
            await TavernHelper.replaceVariables(chatVars, { type: 'chat' });
            console.log(`Next lorebook save index is now persistent: ${nextSaveIndex}`);

            // D. Reset history navigation baseline after a save
            currentHistoryIndex = null;
            localStorage.removeItem('st-beautify-ui-history-nav-index');

            // E. Persist the index of the save that was just completed
            const savedIndex = ((nextSaveIndex - 2 + NUM_LOREBOOK_ENTRIES) % NUM_LOREBOOK_ENTRIES) + 1;
            localStorage.setItem('st-beautify-ui-latest-save-index', savedIndex);
          } catch (error) {
            console.error('保存上下文到世界书失败:', error);
            // 提供更具体的错误信息
            if (error.message.includes('Lorebook not found')) {
              showCustomAlert(`保存上下文失败：世界书不存在。请检查角色卡设置。`);
            } else {
              showCustomAlert(`保存上下文到世界书时发生未知错误: ${error.message}`);
            }
          }
        }

        /**
         * Handles the entire 0-level reply process.
         * 1. Sends the request to the AI.
         * 2. Silently updates the 0th message.
         * 3. Triggers the table-filling extension.
         * 4. Saves the latest context to the worldbook.
         * @param {string} requestMessage - The message to send to the AI.
         */
        async function handleZeroLevelReply(requestMessage) {
            // Check if zero-layer mode is active. If not, do nothing.
            const uiSettings = getUiSettings();
            if (!uiSettings.isZeroLayerMode) {
                console.log('Zero-layer mode is disabled. Skipping handleZeroLevelReply.');
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash('/send ' + requestMessage + ' || /trigger');
                    } catch (e) {
                        showCustomAlert('Error fallback to triggerSlash: ' + e.toString());
