                }
                return;
            }

            const loadingOverlay = context.querySelector('.loading-overlay');
            try {
                if (loadingOverlay && uiSettings.enableGalLoading) {
                    loadingOverlay.style.background = 'rgb(16, 24, 40)';
                    loadingOverlay.style.display = 'flex';
                }

                const aiResponse = await TavernHelper.generate({
                    injects: [{ role: 'user', content: requestMessage, position: 'in_chat', depth: 0, should_scan: true }],
                    should_stream: false,
                });

                if (!aiResponse) throw new Error('AI did not return a response.');

                // 简化流程：直接处理AI响应，不再需要旧插件的优化步骤
                const fallbackExtractor = (text) => {
                    if (!text) return '';
                    const match = text.match(/<gametext>([\s\S]*?)<\/gametext>/);
                    return (match && match[1] ? match[1] : text).replace(/<!--[\s\S]*?-->/g, '').replace(/<[^>]*>/g, '').trim();
                };

                const textForTypingEffect = fallbackExtractor(aiResponse);

                // 2. 使用原始的完整回复进行所有数据处理
                const messages = await getChatMessages('0');
                if (!messages || messages.length === 0) throw new Error('Could not retrieve message at index 0.');

                const messageZero = messages[0];
                messageZero.message = aiResponse; // 更新消息
                await TavernHelper.setChatMessages([messageZero], { refresh: 'none' });

                // 调用新的数据库脚本进行增量更新
                if (parent.AutoCardUpdaterAPI && typeof parent.AutoCardUpdaterAPI.triggerUpdate === 'function') {
                    await parent.AutoCardUpdaterAPI.triggerUpdate();
                } else {
                    console.warn('AutoCardUpdaterAPI.triggerUpdate not found.');
                }

                // [BUGFIX] 构造正确的消息列表用于保存
                const messagesForSave = await getChatMessages(getCurrentMessageId());
                const messageZeroIndex = messagesForSave.findIndex(m => m.id === messageZero.id);
                if (messageZeroIndex !== -1) {
                  messagesForSave[messageZeroIndex] = messageZero;
                }
                await saveContextToLorebook(messagesForSave);

                // 3. 刷新UI - 现在由数据库脚本的回调函数自动处理，无需手动调用
                // const freshData = parent.AutoCardUpdaterAPI.exportTableAsJson();
                // refreshWithData(freshData, false);

                if (loadingOverlay && uiSettings.enableGalLoading) loadingOverlay.style.display = 'none';

                // 4. 最后，使用提取出的、用于显示的部分来启动打字机
                startTypingEffect(textForTypingEffect);

            } catch (error) {
                console.error('0-level reply failed:', error);
                showCustomAlert(`操作失败: ${error.message}`);
                if (loadingOverlay && uiSettings.enableGalLoading) loadingOverlay.style.display = 'none';
            }
        }

        // --- New/Refactored Functions ---

        // Global typing state
        let isTyping = false;
        let typingTimeout = null;
        let currentTypingText = ''; // 新增：用于存储当前正在打字的文本

        async function manualTableFillAndRefresh() {
            const loadingOverlay = context.querySelector('.loading-overlay');
            try {
                if (loadingOverlay) {
                    loadingOverlay.querySelector('span').textContent = '正在手动填表并刷新...';
                    loadingOverlay.style.background = 'rgba(16, 24, 40, 0.8)';
                    loadingOverlay.style.display = 'flex';
                }

                if (parent.AutoCardUpdaterAPI && typeof parent.AutoCardUpdaterAPI.triggerUpdate === 'function') {
