                    await parent.AutoCardUpdaterAPI.triggerUpdate();
                    console.log('Manual database update triggered.');
                } else {
                    throw new Error('AutoCardUpdaterAPI.triggerUpdate not found.');
                }
                // UI refresh will be handled by the callback from the database script.

                if (loadingOverlay) loadingOverlay.style.display = 'none';

            } catch (error) {
                console.error('Manual table fill and refresh failed:', error);
                showCustomAlert(`操作失败: ${error.message}`);
                if (loadingOverlay) loadingOverlay.style.display = 'none';
            } finally {
                if (loadingOverlay) {
                    loadingOverlay.querySelector('span').textContent = '正在生成回复并更新数据...';
                }
            }
        }

        /**
         * Renders text in a container with a typing effect.
         * @param {string} textToType - The text to display.
         */
        function startTypingEffect(textToType) {
          var textContainer = context.querySelector('.maho-scroll-box');
          var skipBtn = context.querySelector('.skip-text-btn');
          var textDisplayArea = context.querySelector('.maho-text-container');

          // 1. Stop any previous typing animation and clear listeners
          if (isTyping) {
            clearTimeout(typingTimeout);
            isTyping = false;
          }
          textDisplayArea.onclick = null;
          skipBtn.onclick = null;

          // 2. Define a unified function to finish the typing effect
          function finishTyping() {
            if (!isTyping) return; // Prevent multiple executions
            isTyping = false;
            clearTimeout(typingTimeout);
            textContainer.innerHTML = textToType; // Show full text

            // Clean up listeners and UI
            textDisplayArea.onclick = null;
            skipBtn.onclick = null;
            skipBtn.style.display = 'none';
          }

          // 3. Handle the actual typing process
          if (textContainer && textToType && textToType.trim() !== '') {
            currentTypingText = textToType; // 保存当前文本
            textContainer.innerHTML = ''; // Clear container before typing
            isTyping = true;
            skipBtn.style.display = 'flex';

            // Set up listeners for this typing session
            skipBtn.onclick = finishTyping;
            textDisplayArea.onclick = finishTyping;

            const uiSettings = getUiSettings();
            const speedLevels = [120, 80, 40, 10, 0]; // 最终版速度差
            const typingDelay = speedLevels[uiSettings.typingSpeed];

            // Handle "instant" speed
            if (typingDelay === 0) {
              finishTyping();
              return;
            }

            function typeNextChar(charIndex) {
              // Check if typing should stop
              if (charIndex >= textToType.length || !isTyping) {
                finishTyping();
                return;
              }

              var charSpan = document.createElement('span');
              charSpan.className = 'typing-char';
              charSpan.textContent = textToType[charIndex];
              textContainer.appendChild(charSpan);
              textContainer.scrollTop = textContainer.scrollHeight;
              typingTimeout = setTimeout(() => typeNextChar(charIndex + 1), typingDelay);
            }

            typeNextChar(0);

          } else if (textContainer) {
            // Handle cases with no text to type
            textContainer.innerHTML = textToType || '';
            skipBtn.style.display = 'none';
            isTyping = false;
          }
        }

        const context = document.querySelector('.maho-interface');
        if (!context) return;

    // --- CONFIGURATION ---
