          };

          var globalTable = tablesByName['全局数据表'] ? tablesByName['全局数据表'].content : [];
          if (globalTable && globalTable.length > 1 && globalTable[1]) {
            var global = globalTable[1];
            data.title = global[1] || '未知地图';
            data.time = global[2] || '未知时间';
            data.externalAreas = (global[3] || '')
              .split(';')
