            };
            pData.interactions = [pStatus[12], pStatus[13], pStatus[14], pStatus[15]].filter(Boolean);
            data.locationImage = pStatus[16] || '';
          }
          data.protagonist = pData;

          var importantCharsTable = tablesByName['重要人物表'] ? tablesByName['重要人物表'].content : [];
          importantCharsTable.slice(1).forEach(function (r) {
            if (!r || !r[1]) return;
            data.importantCharacters.push({
