            if (typeof onConfirm === 'function') onConfirm();
          });
          newCancelBtn.addEventListener('click', function () {
            modal.classList.add('hidden');
          });
        }

        function showCustomPrompt(title, onConfirm) {
          var modal = document.querySelector('#input-modal');
          var titleElement = modal.querySelector('#input-modal-title');
          var inputField = modal.querySelector('#input-modal-field');
          var confirmBtn = modal.querySelector('#input-modal-confirm-btn');

          // The cancel button is now part of the close button logic
          var closeBtn = modal.querySelector('.close-modal-button');

          titleElement.textContent = title;
          inputField.value = '';

          modal.classList.remove('hidden');
          inputField.focus();

          // Use cloning to remove old listeners
          var newConfirmBtn = confirmBtn.cloneNode(true);
          confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);

          var newCloseBtn = closeBtn.cloneNode(true);
          closeBtn.parentNode.replaceChild(newCloseBtn, closeBtn);

          const confirmHandler = () => {
            const inputValue = inputField.value;
            // Only confirm if there is text
            if (inputValue.trim() !== '') {
              modal.classList.add('hidden');
              if (typeof onConfirm === 'function') {
                onConfirm(inputValue);
              }
              cleanup();
            }
          };

          const cancelHandler = () => {
            modal.classList.add('hidden');
            cleanup();
          };

          const keydownHandler = e => {
            if (e.key === 'Enter') {
              e.preventDefault(); // Prevent default form submission behavior
              confirmHandler();
            } else if (e.key === 'Escape') {
              cancelHandler();
            }
          };

          function cleanup() {
            newConfirmBtn.removeEventListener('click', confirmHandler);
            newCloseBtn.removeEventListener('click', cancelHandler);
            inputField.removeEventListener('keydown', keydownHandler);
          }

          newConfirmBtn.addEventListener('click', confirmHandler);
          newCloseBtn.addEventListener('click', cancelHandler);
          inputField.addEventListener('keydown', keydownHandler);
        }

        function closeDropdownPanes() {
            const buttons = context.querySelectorAll('.function-btn');
            const dropdownWrapper = context.querySelector('.dropdown-content-wrapper');
            const allPanes = context.querySelectorAll('.content-pane');

            buttons.forEach(btn => btn.classList.remove('is-active'));
            allPanes.forEach(pane => {
                pane.style.display = 'none';
                pane.classList.remove('is-visible');
            });

            if (dropdownWrapper) {
                dropdownWrapper.style.maxHeight = '0px';
            }
            context.classList.remove('is-open');
        }

        async function sendGameActionRequest(actionDescription, message, onConfirmCallback) {
            if (!protagonistCanMove && (actionDescription.includes('前往') || actionDescription.includes('移动'))) {
                showCustomAlert('你目前不能移动');
                return;
            }

            const uiSettings = getUiSettings();

            // The confirmation pop-up is now removed.
            // The action executes directly.
            if (typeof onConfirmCallback === 'function') {
                onConfirmCallback();
            }

            if (uiSettings.isZeroLayerMode) {
                // 0层填表模式
                handleZeroLevelReply(message);
            } else {
                // 正常Gal模式
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash('/send ' + message + ' || /trigger');
                    } catch (e) {
                        showCustomAlert(e.toString());
                    }
                } else {
                    showCustomAlert("triggerSlash function not found. Action: " + message);
                }
            }
        }

