        document.addEventListener('DOMContentLoaded', function () {
          // --- Static Listeners (only need to be set once) ---
          var buttons = context.querySelectorAll('.function-btn');
          var dropdownWrapper = context.querySelector('.dropdown-content-wrapper');

          function toggleDropdown(targetId, buttonElement) {
            var isActive = buttonElement.classList.contains('is-active');
            var allPanes = context.querySelectorAll('.content-pane');
            buttons.forEach(function (btn) {
              btn.classList.remove('is-active');
            });
            allPanes.forEach(function (pane) {
              pane.style.display = 'none';
              pane.classList.remove('is-visible');
            });
            dropdownWrapper.style.maxHeight = '0px';
            context.classList.remove('is-open');

            if (!isActive) {
              setTimeout(function () {
                var targetPane = context.querySelector('.content-pane[data-content="' + targetId + '"]');
                if (targetPane) {
                  buttonElement.classList.add('is-active');
                  targetPane.style.display = targetId === 'map' || targetId === 'profile' ? 'flex' : 'block';
                  targetPane.classList.add('is-visible');
                  var contentHeight = targetPane.scrollHeight;
                  var maxHeight = window.innerHeight * 0.85;
                  var finalHeight = Math.min(contentHeight, maxHeight);
                  dropdownWrapper.style.maxHeight = finalHeight + 'px';
                  context.classList.add('is-open');
                }
              }, 50);
            }
          }

          buttons.forEach(function (button) {
            button.addEventListener('click', function (e) {
              var targetId = e.currentTarget.dataset.target;
              toggleDropdown(targetId, e.currentTarget);
            });
          });

          // Modal close listeners
          var mainLocationModal = document.querySelector('#main-location-modal');
          var subLocationModal = document.querySelector('#sub-location-modal');
          var mapElementModal = document.querySelector('#map-element-modal');
          var characterModal = document.querySelector('#character-modal');

