            mainLocationModal.querySelector('.close-modal-button').onclick = function () {
              mainLocationModal.classList.add('hidden');
              selectedMain = null;
              selectedSub = null;
            };
          if (subLocationModal)
            subLocationModal.querySelector('.close-modal-button').onclick = function () {
              subLocationModal.classList.add('hidden');
              selectedSub = null;
              if (selectedMain) mainLocationModal.classList.remove('hidden');
            };
          if (mapElementModal)
            mapElementModal.querySelector('.close-modal-button').onclick = function () {
              mapElementModal.classList.add('hidden');
              if (selectedSub) subLocationModal.classList.remove('hidden');
              else if (selectedMain) mainLocationModal.classList.remove('hidden');
            };
          if (characterModal)
            characterModal.querySelector('.close-modal-button').onclick = function () {
              characterModal.classList.add('hidden');
            };
          var inputModal = document.querySelector('#input-modal');
          if (inputModal)
            inputModal.querySelector('.close-modal-button').onclick = function () {
              inputModal.classList.add('hidden');
            };

          ['confirm-modal', 'alert-modal'].forEach(function (id) {
            var modal = document.getElementById(id);
            if (modal) {
              var btn = modal.querySelector('.close-modal-button');
              if (btn)
                btn.onclick = function () {
                  modal.classList.add('hidden');
                };
            }
          });

          // --- Dynamic Data Loading and Refresh ---
          // 1. Initial Load
          runInitialization();

          // Add listener for the new settings button
          const settingsBtn = context.querySelector('.settings-btn');
          if (settingsBtn) {
            settingsBtn.addEventListener('click', openSettingsModal);
          }

          // Add listener for the new manual fill button
          const manualFillBtn = context.querySelector('#manual-fill-btn');
          if (manualFillBtn) {
            manualFillBtn.addEventListener('click', manualTableFillAndRefresh);
          }

          // Add listener for the new fullscreen button
          const fullscreenBtn = context.querySelector('#fullscreen-btn');
          if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', toggleFullScreen);
          }

          // Add listener for fullscreen changes to toggle a class
          document.addEventListener('fullscreenchange', () => {
            const interfaceElement = context; // .maho-interface
            if (document.fullscreenElement === interfaceElement) {
              interfaceElement.classList.add('fullscreen-active');
            } else {
              interfaceElement.classList.remove('fullscreen-active');
