          }

          // Hide popups when clicking outside
          document.addEventListener('click', (e) => {
              if (historyNavPopup && historyNavPopup.style.display === 'flex' && !historyNavPopup.contains(e.target) && !historyNavBtn.contains(e.target)) {
                  historyNavPopup.style.display = 'none';
