        .partner-button { background-color: var(--theme-bg-light); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 7px 14px; font-size: 1rem; color: var(--theme-text-light); cursor: pointer; display: inline-flex; align-items: center; }
        .partner-button i { margin-right: 6px; color: var(--theme-accent-orange); }
        #visual-map-container { position: relative; width: 100%; max-width: 800px; margin: 0 auto 25px auto; border: 2px solid var(--theme-border-light); background-color: var(--theme-bg-light); border-radius: var(--border-radius-base); overflow: hidden; aspect-ratio: 800 / 600; }
        #visual-map { display: block; width: 100%; height: 100%; }
        .map-location-group { cursor: pointer; }
        .map-location-group.selected .map-location-rect { fill: var(--theme-accent-orange); stroke: var(--theme-accent-orange); stroke-width: 2.5px; }
        .map-location-rect { fill: var(--theme-bg-medium); stroke: #6a6f7c; stroke-width: 1.5px; }
        .map-location-label { fill: var(--theme-text-light); text-anchor: middle; dominant-baseline: middle; pointer-events: none; user-select: none; }
        .sub-location-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 12px; margin-bottom: 25px; padding: 18px; background-color: var(--theme-bg-medium); border-radius: var(--border-radius-base); }
        .sub-location-grid.hidden { display: none; }
        .sub-location-button { background-color: var(--theme-bg-light); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 10px 15px; color: var(--theme-text-light); font-size: 1rem; cursor: pointer; }
        .sub-location-button.selected { background: linear-gradient(to bottom, var(--theme-accent-orange-light), var(--theme-accent-orange)); border-color: var(--theme-accent-orange); color: var(--theme-text-dark); font-weight: bold; }
        .info-message { color: var(--theme-text-medium); text-align: center; padding: 20px; font-size: 1rem; }
        .location-details { margin-top: 25px; padding: 25px; background-color: var(--theme-bg-medium); border-radius: var(--border-radius-base); }
        .location-details.hidden { display: none; }
        .action-section { text-align: center; margin-top: 20px; }
        .character-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 10px; margin-bottom: 25px; }
        .character-item { background-color: var(--theme-bg-light); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 9px 12px; font-size: 1rem; color: var(--theme-text-light); cursor: pointer; }
        .modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(44, 49, 58, 0.85); backdrop-filter: blur(4px); z-index: 1000; display: flex; align-items: center; justify-content: center; }
        .modal-overlay.hidden { display: none; }
        .shop-modal-dialog, .inventory-modal-dialog, .character-modal-dialog, .task-modal-dialog { 
            background-color: var(--theme-bg-dark); border: 1px solid var(--theme-border-light); 
            border-radius: var(--border-radius-base); padding: 25px 30px; width: 90%; max-width: 450px; 
            position: relative; 
            display: flex; /* Let modal be a flex container */
            flex-direction: column; /* Arrange children (title, content) vertically */
            max-height: 85vh; /* Prevent modal from exceeding 85% of viewport height */
        }
        .close-modal-button { position: absolute; top: 10px; right: 12px; background: none; border: none; font-size: 26px; color: var(--theme-text-medium); cursor: pointer; z-index: 10; }
        .modal-description-content { margin-bottom: 25px; overflow-y: auto; flex-grow: 1; flex-shrink: 1; min-height: 0; } /* Allow content to scroll, shrink, and be constrained */
        .interaction-options-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 12px; }
        .interaction-button { background-color: var(--theme-bg-light); color: var(--theme-text-light); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 10px 15px; font-size: 14px; cursor: pointer; text-align: center; }
        #skill-items-container, #inventory-items-container, #task-items-container { overflow-y: auto; margin-top: 15px; flex-grow: 1; flex-shrink: 1; min-height: 0; } /* Allow content to scroll, shrink, and be constrained */
        .shop-item, .inventory-item, .task-item, .skill-item { background-color: var(--theme-bg-light); border: 1px solid var(--theme-border-light); border-radius: var(--border-radius-small); padding: 12px 15px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; } /* Modified */
        .use-button { background-color: var(--theme-button-color); color: white; border: none; border-radius: var(--border-radius-small); padding: 6px 12px; cursor: pointer; white-space: nowrap; }
        .use-button:hover { background-color: var(--theme-button-hover-color); }
        /* Task Item Specific CSS */
        .task-item { display: block; } /* Override flex from shop-item if needed */
        .task-item-header { font-weight: bold; margin-bottom: 5px; color: var(--theme-accent-orange-light); }
        .task-item-details { font-size: 0.9rem; color: var(--theme-text-medium); }
        .task-item-details p { margin: 3px 0; }

        /* --- 手机版响应式布局 --- */
        @media (max-width: 768px) {
            body { padding: 5px; --font-size-base: 12px; }
            .map-interface { padding: 15px 10px; }
            .map-header { flex-direction: column; gap: 15px; align-items: center; }
            .map-header h2 { font-size: 1.6rem; }
            .top-right-buttons { 
                display: grid;
                grid-template-columns: repeat(3, 1fr);
                gap: 8px; 
                width: 100%;
            }
            .top-right-buttons .partner-button {
                justify-content: center;
                font-size: 0.9rem; 
                padding: 8px 5px;
            }
            .partner-button i { margin-right: 5px; }
            .partner-button-list, .external-area-buttons { 
                display: grid;
                grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
                gap: 8px;
            }
            #visual-map-container { aspect-ratio: 1 / 1; }
            .map-location-label { font-size: 0.85em; }
            .sub-location-grid { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); padding: 12px; }
            .character-list { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); }
            .shop-modal-dialog, .inventory-modal-dialog, .character-modal-dialog, .task-modal-dialog, .confirm-modal-dialog { padding: 20px 15px; width: 95%; }
            .interaction-options-grid { grid-template-columns: 1fr; }
        }
        /* Custom Confirm/Alert Modal Styles */
        .confirm-modal-dialog {
            background-color: var(--theme-bg-dark);
            border: 1px solid var(--theme-accent-orange);
            border-radius: var(--border-radius-base);
            padding: 25px 30px;
            width: 90%;
            max-width: 400px;
            text-align: center;
        }
        #confirm-modal-text, #alert-modal-text {
            margin: 20px 0;
            font-size: 1.1rem;
            line-height: 1.5;
            color: var(--theme-text-light);
            white-space: pre-wrap; /* To respect \n in confirm message */
        }
        .confirm-modal-buttons {
            display: flex;
            justify-content: space-around;
            gap: 20px;
            margin-top: 10px;
        }
        .confirm-modal-buttons .interaction-button {
            flex-grow: 1;
        }
        .confirm-modal-buttons .interaction-button.confirm {
            background-color: var(--theme-button-color);
            color: white;
        }
        .confirm-modal-buttons .interaction-button.confirm:hover {
            background-color: var(--theme-button-hover-color);
        }
    </style>
</head>
<body>
    <div class="map-interface">
        <div class="map-header">
            <h2 id="map-title"></h2>
            <div class="header-info"><span id="map-time"></span></div>
             <div class="top-right-buttons">
                <button class="partner-button" id="skill-button"><i class="fas fa-book"></i> 技能</button>
                <button class="partner-button" id="inventory-button"><i class="fas fa-briefcase"></i> 背包</button>
                <button class="partner-button" id="task-button"><i class="fas fa-tasks"></i> 任务</button>
            </div>
        </div>
        <div id="current-important-characters" class="current-partners-section hidden">
             <div class="section-title"><i class="fas fa-star"></i> 当前地图重要人物</div>
             <div id="important-character-buttons" class="partner-button-list"></div>
        </div>
        <div id="visual-map-container"><svg id="visual-map" viewBox="0 0 800 600" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg"></svg></div>
        <div id="external-areas" class="external-areas-section hidden">
             <div class="section-title"><i class="fas fa-globe-asia"></i> 可前往的外部区域</div>
             <div id="external-area-buttons" class="external-area-buttons"></div>
        </div>
        <div id="sub-locations" class="sub-location-grid hidden"></div>
        <div id="location-details" class="location-details hidden">
            <div class="detail-header"><i class="fas fa-map-marker-alt"></i> <span id="selected-location"></span></div>
            <div class="detail-content">
                <div class="character-section">
                    <div class="section-title"><i class="fas fa-users"></i> 此地互动元素</div> <!-- Changed Title -->
                    <div id="location-characters" class="character-list"></div>
                </div>
            </div>
            <div class="action-section">
                <button id="go-to-sub-location-btn" class="partner-button" disabled><i class="fas fa-walking"></i> 到那里去</button>
            </div>
        </div>
    </div>

    <div id="character-modal" class="modal-overlay hidden">
        <div class="character-modal-dialog">
            <button id="close-modal-btn" class="close-modal-button">&times;</button>
            <h4 id="modal-character-name"></h4>
            <div id="modal-character-description" class="modal-description-content"></div>
            <div id="modal-interaction-options" class="interaction-options-grid"></div>
        </div>
    </div>
    <div id="skill-modal" class="modal-overlay hidden">
        <div class="shop-modal-dialog">
            <button id="close-skill-btn" class="close-modal-button">&times;</button>
            <h4><i class="fas fa-book"></i> 技能</h4>
            <div id="skill-items-container"></div>
        </div>
    </div>
    <div id="inventory-modal" class="modal-overlay hidden">
        <div class="inventory-modal-dialog">
            <button id="close-inventory-btn" class="close-modal-button">&times;</button>
            <h4><i class="fas fa-briefcase"></i> 背包</h4>
            <div id="inventory-items-container"></div>
        </div>
    </div>

    <div id="task-modal" class="modal-overlay hidden"> <!-- Added Task Modal -->
        <div class="task-modal-dialog"> <!-- Applied task-modal-dialog class -->
            <button id="close-task-btn" class="close-modal-button">&times;</button>
            <h4><i class="fas fa-tasks"></i> 当前任务</h4>
            <div id="task-items-container"></div> <!-- Applied task-items-container class -->
        </div>
    </div>

    <div id="confirm-modal" class="modal-overlay hidden">
        <div class="confirm-modal-dialog">
            <h4>请确认操作</h4>
            <div id="confirm-modal-text" class="modal-description-content"></div>
            <div class="confirm-modal-buttons">
                <button id="confirm-modal-cancel-btn" class="interaction-button">取消</button>
                <button id="confirm-modal-confirm-btn" class="interaction-button confirm">确认</button>
            </div>
        </div>
    </div>

    <div id="alert-modal" class="modal-overlay hidden">
        <div class="confirm-modal-dialog">
             <h4>提示</h4>
             <div id="alert-modal-text" class="modal-description-content"></div>
             <div class="confirm-modal-buttons">
                 <button id="alert-modal-ok-btn" class="interaction-button confirm">好的</button>
             </div>
        </div>
    </div>

    <script>
        var tableDataRaw = `{{GET_ALL_TABLES_JSON}}`; // Treat macro as string initially
        var tableData = {}; // Initialize as empty object
        var mapData = null, selectedMain = null, selectedSub = null;
        var protagonistCanMove = true; // Default assumption: protagonist can move

        try {
            // Attempt to parse the JSON string from the macro
            tableData = JSON.parse(tableDataRaw);
        } catch (e) {
             console.error("Error parsing tableData JSON:", e);
             console.error("Raw tableData string:", tableDataRaw);
             // Handle error state - maybe show an error message in the UI
             // For now, we'll let processJsonData handle the empty tableData object
        }

        function processJsonData(json) {
            var tablesByName = {};
            // Basic check if json is valid
            if (!json || typeof json !== 'object') {
                 console.error("Invalid JSON data received:", json);
                 return { title: '错误', time: '无法加载数据', locations: [], importantCharacters: [], externalAreas: [], currentUserPosition: {x: 400, y: 300}, shop: [], inventory: [], tasks: [] };
            }

            // Extract tables by name, assuming structure like {"sheet_ID": {name: "Table Name", content: [...]}}
            for (var sheetId in json) {
                if (Object.prototype.hasOwnProperty.call(json, sheetId) && json[sheetId] && json[sheetId].name && json[sheetId].content) { 
                    tablesByName[json[sheetId].name] = json[sheetId];
                }
            }

            var data = { title: '', time: '', locations: [], importantCharacters: [], externalAreas: [], currentUserPosition: {}, skills: [], inventory: [], tasks: [] };

            // --- Global Data --- (Indices from 1)
            var globalTable = tablesByName['全局数据表'];
            if (globalTable && globalTable.content && globalTable.content.length > 1 && globalTable.content[1]) {
                var global = globalTable.content[1];
                data.title = global[1] || '未知地图'; // Col 1
                data.time = global[2] || '未知时间'; // Col 2
                data.externalAreas = (global[3] || '').split(';').map(function(s) { return s.trim(); }).filter(Boolean); // Col 3
            } else {
                console.warn("Global data table missing or invalid.");
                data.title = '错误'; data.time = '无法加载全局数据';
            }

            // --- Protagonist --- (Two tables now)
            var protagonistInfoTable = tablesByName['主角信息'];
            var protagonistStatusTable = tablesByName['主角状态'];
            var protagonistData = { isProtagonist: true, name: '主角', details: { attributes: {} }, interactions: [] };

            if (protagonistInfoTable && protagonistInfoTable.content && protagonistInfoTable.content.length > 1 && protagonistInfoTable.content[1]) {
                var pInfo = protagonistInfoTable.content[1];
                // Indices: 1:名称, 2:性别/年龄, 3:外貌, 4:职业/身份, 5:背景, 6:性格
                protagonistData.name = pInfo[1] || '主角';
                protagonistData.genderAge = pInfo[2];
                protagonistData.appearance = pInfo[3];
                protagonistData.profession = pInfo[4];
                protagonistData.details.backstory = pInfo[5];
                protagonistData.details.personality = pInfo[6];
            } else {
                console.warn("Protagonist Info table missing or invalid.");
                protagonistData.name = '主角 (信息数据错误)';
            }

            if (protagonistStatusTable && protagonistStatusTable.content && protagonistStatusTable.content.length > 1 && protagonistStatusTable.content[1]) {
                var pStatus = protagonistStatusTable.content[1];
                // Indices: 1:状态, 2:移动, 3:金钱, 4:主地点, 5:次地点, 6:X, 7:Y, 8-13:六维, 14-17:互动
                protagonistData.details.status = pStatus[1];
                protagonistData.details.canMove = pStatus[2];
                protagonistData.details.money = pStatus[3];
                protagonistCanMove = !(pStatus[2] && pStatus[2].trim().toLowerCase() === '否');

                var posX = parseInt(pStatus[6]);
                var posY = parseInt(pStatus[7]);
                data.currentUserPosition = { x: !isNaN(posX) ? posX : 400, y: !isNaN(posY) ? posY : 300 };

                protagonistData.details.attributes = {
                    strength: pStatus[8],
                    intelligence: pStatus[9],
                    dexterity: pStatus[10],
                    constitution: pStatus[11],
                    charisma: pStatus[12],
                    perception: pStatus[13]
                };
                protagonistData.interactions = [pStatus[14], pStatus[15], pStatus[16], pStatus[17]].filter(Boolean);
            } else {
                console.warn("Protagonist Status table missing or invalid.");
                protagonistData.name = '主角 (状态数据错误)';
                data.currentUserPosition = {x: 400, y: 300};
            }
            data.importantCharacters.push(protagonistData);

            // --- Important Characters --- (Indices are 1-based)
            var importantCharsTable = tablesByName['重要人物表'];
            if (importantCharsTable && importantCharsTable.content) {
                importantCharsTable.content.slice(1).forEach(function(row) { 
                    if (!row || !row[1]) return; 

                    // Correct indices based on table_data.json: 1:姓名, 2:性别/年龄, 3:外貌, 4:职业, 5:性格, 6:背景, 7:关系, 8:状态, 9:物品, 10:能力, 11:好感度, 12:想法, 13-16:互动, 17:是否离场, 18:离场轮数, 19:剧情关键角色
                    var charData = { 
                        name: row[1], // Col 1
                        genderAge: row[2], // Col 2
                        appearance: row[3], // Col 3
                        profession: row[4], // Col 4
                        personality: row[5], // Col 5
                        backstory: row[6], // Col 6
                        relationship: row[7], // Col 7
                        status: row[8], // Col 8
                        items: row[9], // Col 9
                        abilities: row[10], // Col 10
                        affinity: row[11], // Col 11
                        thoughts: row[12], // Col 12
                        description: "状态: " + (row[8] || '未知') + " | 关系: " + (row[7] || '未知'), // Cols 8, 7
                        interactions: [row[13], row[14], row[15], row[16]].filter(Boolean), // Cols 13-16
                        isAway: row.length > 17 ? row[17] : undefined, // Col 17
                        awayTurns: row.length > 18 ? row[18] : undefined, // Col 18
                        isPlotCritical: row.length > 19 ? row[19] : undefined // Col 19
                     };

                     data.importantCharacters.push(charData); 
                });
            }

            // --- Skills --- (Indices are 1-based, from '主角技能表')
            var skillsTable = tablesByName['主角技能表'];
            data.skills = []; // Ensure skills array exists
            if (skillsTable && skillsTable.content) {
                skillsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1]) return; // Skip if row is invalid or name (col 1) missing
                    data.skills.push({
                        name: row[1], // Col 1: 技能名称
                        effect: row[2], // Col 2: 技能效果
                        level: row[3], // Col 3: 技能等级
                        mastery: row[4] // Col 4: 技能熟练度
                    });
                });
            }

            // --- Inventory --- (Indices are 1-based)
            var inventoryTable = tablesByName['背包物品表'];
            if (inventoryTable && inventoryTable.content) {
                inventoryTable.content.slice(1).forEach(function(row) {
                     if (!row || !row[1]) return; 
                    // Correct indices based on table_data.json: 1:名称, 3:描述
                    data.inventory.push({ 
                        name: row[1], // Col 1
                        description: row[3] // Col 3 
                    });
                });
            }

            // --- Sub Locations --- (Indices are 1-based)
            var subLocationsMap = new Map();
            var subLocationsTable = tablesByName['次级地点表'];
            if (subLocationsTable && subLocationsTable.content) {
                subLocationsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1] || !row[2]) return; 
                    // Correct indices based on table_data.json: 1:次级名称, 2:所属主地点, 3:环境描述
                    var subName = row[1], mainName = row[2], subDesc = row[3] || ''; 
                    if (!subLocationsMap.has(mainName)) subLocationsMap.set(mainName, []);
                    subLocationsMap.get(mainName).push({ name: subName, description: subDesc, elements: [] }); 
                });
            }

            // --- Map Elements --- (Indices are 1-based)
            var elementsTable = tablesByName['地图元素表'];
            if (elementsTable && elementsTable.content) {
                elementsTable.content.slice(1).forEach(function(row) {
                    if (!row || !row[1] || !row[4]) return; 
                    // Correct indices based on table_data.json: 1:名称, 2:类型, 3:描述, 4:所属次级地点, 5:状态, 6:要求, 7-10:互动
                    var element = { 
                        name: row[1], // Col 1
                        type: row[2] || '未知', // Col 2
                        description: row[3] || '', // Col 3
                        status: row[5] || '未知', // Col 5
                        requirements: row[6] || '无', // Col 6
                        interactions: [row[7], row[8], row[9], row[10]].filter(Boolean) // Col 7-10
                    };
                    var subLocationName = row[4]; // Col 4
                    var found = false;
                    var mainLocIter = subLocationsMap.values();
                    var mainLocSubs;
                    while (!found && !(mainLocSubs = mainLocIter.next()).done) {
                         var sub = mainLocSubs.value.find(function(s) { return s.name === subLocationName; });
                         if (sub) {
                            sub.elements.push(element);
                            found = true;
                         }
                    }
                    if (!found) { console.warn("Element '" + element.name + "' assigned to non-existent sub-location '" + subLocationName + "'"); }
                });
            }

            // --- Tasks --- (Indices are 1-based)
            var tasksTable = tablesByName['任务与事件表'];
             if (tasksTable && tasksTable.content) {
                 tasksTable.content.slice(1).forEach(function(row) {
                     if (!row || !row[1]) return; // Skip if row invalid or name (col 1) missing
                     data.tasks.push({ 
                         name: row[1], // Col 1: 任务名称
                         description: row[2], // Col 2: 任务描述
                         publisher: row[3], // Col 3: 发布者
                         keyInfo: row[4], // Col 4: 任务关键信息
                         progress: row[5], // Col 5: 任务进度
                         timeLimit: row[6], // Col 6: 任务时限
                         reward: row[7] // Col 7: 任务奖励
                     });
                 });
             }

            // --- Main Locations --- (Indices are 1-based)
            var mainLocationsTable = tablesByName['主要地点表'];
            if (mainLocationsTable && mainLocationsTable.content) {
                 mainLocationsTable.content.slice(1).forEach(function(row) {
                     if (!row) return; 
                     // Correct indices based on table_data.json: 1:名称, 2:X, 3:Y, 4:宽, 5:高, 6:类型, 7:描述, 8:区域
                     var name = row[1] || '未命名地点'; // Col 1
                     var x = parseInt(row[2]); var y = parseInt(row[3]); // Col 2, Col 3
                     var width = parseInt(row[4]); var height = parseInt(row[5]); // Col 4, Col 5

                     if (name && !isNaN(x) && !isNaN(y) && !isNaN(width) && width > 0 && !isNaN(height) && height > 0) {
                         data.locations.push({ 
                             name: name, x: x, y: y, width: width, height: height, 
                             type: row[6] || '未知', // Col 6
                             description: row[7] || '', // Col 7
                             region: row[8] || '未知', // Col 8
                             subLocations: subLocationsMap.get(name) || []
                         });
                     } else {
                         console.warn("Skipping invalid/incomplete location data:", row);
                     }
                 });
             } else {
                  console.warn("Main locations table missing or invalid.");
             }

            return data;
        }

        function renderMapInterface(data) {
            document.getElementById('map-title').textContent = data.title;
            document.getElementById('map-time').textContent = data.time;
            var svg = document.getElementById('visual-map'), ns = "http://www.w3.org/2000/svg";
            svg.innerHTML = ''; // Clear previous map

            if (!data || !data.locations || !Array.isArray(data.locations)) {
                console.error("Cannot render map: Invalid locations data.");
                return;
            }

            data.locations.forEach(function(l) {
                 // Double check location properties needed for rendering
                 if (typeof l.x !== 'number' || typeof l.y !== 'number' || typeof l.width !== 'number' || l.width <= 0 || typeof l.height !== 'number' || l.height <= 0 || !l.name) {
                     console.warn("Skipping rendering invalid location:", l);
                     return;
                 }

                var g = document.createElementNS(ns, 'g');
                g.setAttribute('transform', 'translate(' + l.x + ', ' + l.y + ')');
                g.classList.add('map-location-group');
