                 document.getElementById('skill-button').addEventListener('click', function() { document.getElementById('skill-modal').classList.remove('hidden'); });
                 document.getElementById('close-skill-btn').addEventListener('click', function() { document.getElementById('skill-modal').classList.add('hidden'); });
                 document.getElementById('inventory-button').addEventListener('click', function() { document.getElementById('inventory-modal').classList.remove('hidden'); });
                 document.getElementById('close-inventory-btn').addEventListener('click', function() { document.getElementById('inventory-modal').classList.add('hidden'); });
                 document.getElementById('task-button').addEventListener('click', function() { document.getElementById('task-modal').classList.remove('hidden'); }); // Added listener for task button
                 document.getElementById('close-task-btn').addEventListener('click', function() { document.getElementById('task-modal').classList.add('hidden'); }); // Added listener for task close button

             } catch (e) {
