          gap: 4px; /* Space between the two rows */
        }

        /* Top Row: Larger buttons with text */
        .bottom-function-bar {
          order: 1; /* First row */
          width: auto; /* Let it shrink to fit content */
          max-width: 100%; /* Ensure it doesn't exceed screen width */
          gap: 4px; /* Further reduced gap */
          padding: 0;
          flex-wrap: nowrap; /* Prevent wrapping */
          justify-content: center;
          flex-shrink: 1; /* Allow the bar to shrink */
