        ) {
          document.addEventListener('DOMContentLoaded', function () {
            document.body.innerHTML =
              '<div style="color:red; text-align:center; padding: 20px; font-family: sans-serif;">错误：SillyTavern API 未找到。此界面必须在 SillyTavern 环境中运行。</div>';
          });
          return; // Stop script execution
