              showCustomAlert(`错误：角色卡指定的世界书 "${LOREBOOK_NAME}" 未找到。`);
              return;
            }

            const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
            const currentContextKey = `${LOREBOOK_KEY_PREFIX}${lorebookSaveIndex}`;
            const currentTableKey = `${TABLE_KEY_PREFIX}${lorebookSaveIndex}`;

            let contextEntry = allEntries.find(entry => entry.comment === currentContextKey);
            let tableEntry = allEntries.find(entry => entry.comment === currentTableKey);

            // 封装一个创建或更新条目的函数，避免代码重复
            const createOrUpdateEntry = async (key, content, existingEntry) => {
              const entryType = key.startsWith(TABLE_KEY_PREFIX) ? 'selective' : 'constant';
              if (!existingEntry) {
                // Create new entry
                console.log(`在 "${LOREBOOK_NAME}" 中创建世界书条目: ${key}`);
                const newEntryData = {
                  comment: key,
                  keys: [key],
                  content: content,
                  enabled: true,
                  type: entryType,
                  position: 'after_char',
