              .join('\n---\n');

            await createOrUpdateEntry(currentContextKey, contextContent, contextEntry);
            console.log(`上下文已保存到 "${LOREBOOK_NAME}" 的条目: ${currentContextKey}`);

            // 2. 处理并保存表格数据
