            await createOrUpdateEntry(currentTableKey, tableContent, tableEntry);
            console.log(`表格数据已保存到 "${LOREBOOK_NAME}" 的条目: ${currentTableKey}`);

            // B. 循环到下一个索引 (1-5)
            const nextSaveIndex = (lorebookSaveIndex % NUM_ENTRIES) + 1;

            // C. Save the next index back to chat variables
            chatVars[INDEX_VAR_KEY] = nextSaveIndex;
            await TavernHelper.replaceVariables(chatVars, { type: 'chat' });
