            // D. Reset history navigation baseline after a save
            currentHistoryIndex = null;
            localStorage.removeItem('st-beautify-ui-history-nav-index');

            // E. Persist the index of the save that was just completed
            const savedIndex = ((nextSaveIndex - 2 + NUM_LOREBOOK_ENTRIES) % NUM_LOREBOOK_ENTRIES) + 1;
            localStorage.setItem('st-beautify-ui-latest-save-index', savedIndex);
