          var inventoryTable = tablesByName['背包物品表'] ? tablesByName['背包物品表'].content : [];
          inventoryTable.slice(1).forEach(function (r) {
            if (r && r[1]) data.inventory.push({ name: r[1], quantity: r[2], description: r[3] });
          });

          var tasksTable = tablesByName['任务与事件表'] ? tablesByName['任务与事件表'].content : [];
          tasksTable.slice(1).forEach(function (r) {
            // According to schema: 1:Name, 2:Description, 5:Progress
            if (r && r[1]) data.tasks.push({ name: r[1], description: r[2], progress: r[5] });
          });

          var subLocs = {};
          var subLocsTable = tablesByName['次级地点表'] ? tablesByName['次级地点表'].content : [];
          subLocsTable.slice(1).forEach(function (r) {
            if (r && r[2] && r[1]) {
              if (!subLocs[r[2]]) subLocs[r[2]] = [];
              subLocs[r[2]].push({ name: r[1], description: r[3], elements: [] });
            }
          });

          var elementsTable = tablesByName['地图元素表'] ? tablesByName['地图元素表'].content : [];
          elementsTable.slice(1).forEach(function (r) {
            if (r && r[1] && r[4]) {
              for (var mainLocName in subLocs) {
                var sub = subLocs[mainLocName].find(function (i) {
                  return i.name === r[4];
                });
                if (sub) {
                  sub.elements.push({
                    name: r[1],
                    type: r[2],
                    description: r[3],
                    interactions: [r[7], r[8], r[9], r[10]].filter(Boolean),
                  });
                  break;
                }
              }
            }
          });

          var mainLocsTable = tablesByName['主要地点表'] ? tablesByName['主要地点表'].content : [];
          mainLocsTable.slice(1).forEach(function (r) {
            // According to schema: 1:Name, 2:X, 3:Y, 4:W, 5:H, 7:Description
            if (r && r[1]) {
              var x = parseInt(r[2]),
                y = parseInt(r[3]),
                w = parseInt(r[4]),
                h = parseInt(r[5]);
              if (!isNaN(x) && !isNaN(y) && !isNaN(w) && !isNaN(h)) {
                data.locations.push({
                  name: r[1],
                  x: x,
                  y: y,
                  width: w,
                  height: h,
                  description: r[7],
                  subLocations: subLocs[r[1]] || [],
                });
              }
            }
          });

          data.protagonistLocationName = pData.currentLocationName;

          // Dynamically calculate protagonist position based on location
          if (data.protagonistLocationName) {
            var protagonistLocation = data.locations.find(function (loc) {
              return loc.name === data.protagonistLocationName;
            });
            if (protagonistLocation) {
              data.currentUserPosition = {
                x: protagonistLocation.x + protagonistLocation.width / 2,
                y: protagonistLocation.y + protagonistLocation.height / 2,
              };
            }
          }
          if (!data.currentUserPosition || !data.currentUserPosition.x) {
            data.currentUserPosition = { x: 400, y: 300 }; // Fallback
          }

          return data;
        }

        function renderMapInterface(data) {
          if (!data || !data.locations) return;
          var container = context.querySelector('#map-container-in-pane');

          // Restore viewBox and preserveAspectRatio to maintain proportions
          container.innerHTML =
            '<div class="map-header">' +
            '    <h2 id="map-title">' +
            (data.title || '') +
            '</h2>' +
            '</div>' +
            '<div id="visual-map-container"><svg id="visual-map" viewBox="0 0 800 600" preserveAspectRatio="xMidYMid meet"></svg></div>' +
            '<div id="external-areas-bar"></div>';

          var svg = container.querySelector('#visual-map'),
            ns = 'http://www.w3.org/2000/svg';

          // Dynamically calculate viewBox to fit all locations
          var vW = 800, vH = 600; // Default values
          if (data.locations && data.locations.length > 0) {
            var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
            data.locations.forEach(function(l) { 
                minX = Math.min(minX, l.x); 
                minY = Math.min(minY, l.y); 
                maxX = Math.max(maxX, l.x + l.width); 
                maxY = Math.max(maxY, l.y + l.height); 
            });
            var padding = Math.max((maxX - minX) * 0.1, (maxY - minY) * 0.1, 50);
            var vX = minX - padding;
            var vY = minY - padding;
            vW = (maxX - minX) + (padding * 2);
            vH = (maxY - minY) + (padding * 2);
            svg.setAttribute('viewBox', vX + ' ' + vY + ' ' + vW + ' ' + vH);
          }

          data.locations.forEach(function (l) {
            var g = document.createElementNS(ns, 'g');
            g.classList.add('map-location-group');
            g.addEventListener('click', function () {
              openMainLocationModal(l);
            });
            var r = document.createElementNS(ns, 'rect');
            r.setAttribute('x', l.x);
            r.setAttribute('y', l.y);
            r.setAttribute('width', l.width);
            r.setAttribute('height', l.height);
            r.classList.add('map-location-rect');
            var t = document.createElementNS(ns, 'text');
            t.setAttribute('x', l.x + l.width / 2);
            t.setAttribute('y', l.y + l.height / 2);
            t.classList.add('map-location-label');
            t.textContent = l.name;
            g.appendChild(r);
