          if (data.currentUserPosition) {
            var dot = document.createElementNS(ns, 'circle');
            dot.setAttribute('cx', data.currentUserPosition.x);
            dot.setAttribute('cy', data.currentUserPosition.y);
            var dR = Math.min(vW, vH) * 0.008;
            dot.setAttribute('r', Math.max(5, dR)); 
            dot.setAttribute('fill', 'red');
            dot.setAttribute('stroke', 'white');
            dot.setAttribute('stroke-width', dR * 0.3);
            svg.appendChild(dot);
          }

          var externalAreasBar = container.querySelector('#external-areas-bar');
          externalAreasBar.innerHTML = ''; // Clear previous buttons

          if (data.externalAreas && data.externalAreas.length > 0) {
            data.externalAreas.forEach(function (areaName) {
