            modal.classList.add('hidden');
          });
        }

        function showCustomPrompt(title, onConfirm) {
          var modal = document.querySelector('#input-modal');
          var titleElement = modal.querySelector('#input-modal-title');
          var inputField = modal.querySelector('#input-modal-field');
          var confirmBtn = modal.querySelector('#input-modal-confirm-btn');

          // The cancel button is now part of the close button logic
          var closeBtn = modal.querySelector('.close-modal-button');

          titleElement.textContent = title;
          inputField.value = '';

          modal.classList.remove('hidden');
          inputField.focus();

          // Use cloning to remove old listeners
          var newConfirmBtn = confirmBtn.cloneNode(true);
          confirmBtn.parentNode.replaceChild(newConfirmBtn, confirmBtn);

          var newCloseBtn = closeBtn.cloneNode(true);
          closeBtn.parentNode.replaceChild(newCloseBtn, closeBtn);

          const confirmHandler = () => {
            const inputValue = inputField.value;
            // Only confirm if there is text
            if (inputValue.trim() !== '') {
              modal.classList.add('hidden');
              if (typeof onConfirm === 'function') {
                onConfirm(inputValue);
              }
              cleanup();
            }
          };

          const cancelHandler = () => {
            modal.classList.add('hidden');
            cleanup();
          };

          const keydownHandler = e => {
            if (e.key === 'Enter') {
              e.preventDefault(); // Prevent default form submission behavior
              confirmHandler();
            } else if (e.key === 'Escape') {
              cancelHandler();
            }
          };

          function cleanup() {
            newConfirmBtn.removeEventListener('click', confirmHandler);
            newCloseBtn.removeEventListener('click', cancelHandler);
            inputField.removeEventListener('keydown', keydownHandler);
          }

          newConfirmBtn.addEventListener('click', confirmHandler);
          newCloseBtn.addEventListener('click', cancelHandler);
          inputField.addEventListener('keydown', keydownHandler);
        }

        function closeDropdownPanes() {
            const buttons = context.querySelectorAll('.function-btn');
            const dropdownWrapper = context.querySelector('.dropdown-content-wrapper');
            const allPanes = context.querySelectorAll('.content-pane');

            buttons.forEach(btn => btn.classList.remove('is-active'));
            allPanes.forEach(pane => {
                pane.style.display = 'none';
                pane.classList.remove('is-visible');
            });

            if (dropdownWrapper) {
                dropdownWrapper.style.maxHeight = '0px';
            }
            context.classList.remove('is-open');
        }

        async function sendGameActionRequest(actionDescription, message, onConfirmCallback) {
            if (!protagonistCanMove && (actionDescription.includes('前往') || actionDescription.includes('移动'))) {
                showCustomAlert('你目前不能移动');
                return;
            }

            const uiSettings = getUiSettings();

            // The confirmation pop-up is now removed.
            // The action executes directly.
            if (typeof onConfirmCallback === 'function') {
                onConfirmCallback();
            }

            if (uiSettings.isZeroLayerMode) {
                // 0层填表模式
                handleZeroLevelReply(message);
            } else {
                // 正常Gal模式
                if (typeof triggerSlash === 'function') {
                    try {
                        triggerSlash('/send ' + message + ' || /trigger');
                    } catch (e) {
                        showCustomAlert(e.toString());
                    }
                } else {
                    showCustomAlert("triggerSlash function not found. Action: " + message);
                }
            }
        }

        // --- Main Initialization & Data Refresh ---
        async function refreshWithData(data, shouldUpdateStory = true) {
          mapData = processJsonData(data);

          // Adjust layout to prevent overlaps before rendering
          if (mapData && mapData.locations) {
            mapData.locations = adjustLayoutForOverlaps(mapData.locations);
          }

          if (!mapData) {
            console.error('Refresh failed: No data processed');
            return;
          }

          // Populate top bar
          context.querySelector('#info-time span:last-child').textContent = mapData.time;
          context.querySelector('#info-location span:last-child').textContent = mapData.title;
          context.querySelector('#info-money span:last-child').textContent = mapData.money;

          // Determine image paths based on setting
          const uiSettings = getUiSettings();

          activeLocationPath = uiSettings.useNetworkAssets ? config.networkLocationImagePath : config.locationImagePath;
          activeCharacterPath = uiSettings.useNetworkAssets ? config.networkCharacterImagePath : config.characterImagePath;

          // Set scene image and interface background
          var sceneImageElement = context.querySelector('#scene-image');
          var locationImageName = mapData.locationImage;

          // Define the original, hardcoded default background
          const hardcodedDefaultBackgroundImage = 'https://tc.z.wiki/autoupload/f/Mni8OcLITdv7Gy5JSasVq1jzZpLi8sXGZgGJW-1aOMmyl5f0KlZfm6UsKj-HyTuv/20250727/KLXB/1242X1920/4CEEB99D40E5731E26A096256FF3B299.jpg';
          // Check for a user-uploaded custom background
          const customDefaultBackgroundImage = localStorage.getItem('st-beautify-ui-custom-default-background');
          // Use the custom one if it exists, otherwise fall back to the hardcoded one
          const finalDefaultBackgroundImage = customDefaultBackgroundImage || hardcodedDefaultBackgroundImage;

          var hasImage = locationImageName && locationImageName.trim() !== '';
          var imageUrl = hasImage ? activeLocationPath + locationImageName + '.png' : finalDefaultBackgroundImage;

          sceneImageElement.src = imageUrl;
          sceneImageElement.style.display = 'block';
          context.style.backgroundColor = '#101828';
          context.style.backdropFilter = 'none';
          context.style.webkitBackdropFilter = 'none';

          sceneImageElement.onerror = function () {
            // When an image fails to load
            // If the failed source is not the final default background, try loading the final default background.
            if (this.src !== finalDefaultBackgroundImage) {
              console.log('Image failed to load, switching to default background:', finalDefaultBackgroundImage);
              this.src = finalDefaultBackgroundImage;
            } else {
              // If even the final default background fails, hide the image and show the glass effect.
              console.log('Default background also failed to load, showing blur effect.');
              this.style.display = 'none';
              context.style.backgroundColor = 'rgba(16, 24, 40, 0.05)';
              context.style.backdropFilter = 'blur(8px)';
