        async function runInitialization() {
          var data;
          try {
            data = parent.AutoCardUpdaterAPI.exportTableAsJson();
          } catch (e) {
            console.error('Error calling exportTableAsJson for initialization:', e);
            data = {};
          }
          await refreshWithData(data);
        }

        document.addEventListener('DOMContentLoaded', function () {
          // --- Static Listeners (only need to be set once) ---
          var buttons = context.querySelectorAll('.function-btn');
          var dropdownWrapper = context.querySelector('.dropdown-content-wrapper');

          function toggleDropdown(targetId, buttonElement) {
            var isActive = buttonElement.classList.contains('is-active');
            var allPanes = context.querySelectorAll('.content-pane');
            buttons.forEach(function (btn) {
              btn.classList.remove('is-active');
            });
            allPanes.forEach(function (pane) {
              pane.style.display = 'none';
              pane.classList.remove('is-visible');
            });
            dropdownWrapper.style.maxHeight = '0px';
            context.classList.remove('is-open');

            if (!isActive) {
              setTimeout(function () {
                var targetPane = context.querySelector('.content-pane[data-content="' + targetId + '"]');
                if (targetPane) {
                  buttonElement.classList.add('is-active');
                  targetPane.style.display = targetId === 'map' || targetId === 'profile' ? 'flex' : 'block';
                  targetPane.classList.add('is-visible');
                  var contentHeight = targetPane.scrollHeight;
                  var maxHeight = window.innerHeight * 0.85;
                  var finalHeight = Math.min(contentHeight, maxHeight);
                  dropdownWrapper.style.maxHeight = finalHeight + 'px';
                  context.classList.add('is-open');
                }
              }, 50);
            }
          }

          buttons.forEach(function (button) {
            button.addEventListener('click', function (e) {
              var targetId = e.currentTarget.dataset.target;
              toggleDropdown(targetId, e.currentTarget);
            });
          });

          // Modal close listeners
          var mainLocationModal = document.querySelector('#main-location-modal');
          var subLocationModal = document.querySelector('#sub-location-modal');
          var mapElementModal = document.querySelector('#map-element-modal');
          var characterModal = document.querySelector('#character-modal');

          if (mainLocationModal)
            mainLocationModal.querySelector('.close-modal-button').onclick = function () {
              mainLocationModal.classList.add('hidden');
              selectedMain = null;
              selectedSub = null;
            };
          if (subLocationModal)
            subLocationModal.querySelector('.close-modal-button').onclick = function () {
              subLocationModal.classList.add('hidden');
              selectedSub = null;
              if (selectedMain) mainLocationModal.classList.remove('hidden');
            };
          if (mapElementModal)
            mapElementModal.querySelector('.close-modal-button').onclick = function () {
              mapElementModal.classList.add('hidden');
              if (selectedSub) subLocationModal.classList.remove('hidden');
              else if (selectedMain) mainLocationModal.classList.remove('hidden');
            };
          if (characterModal)
            characterModal.querySelector('.close-modal-button').onclick = function () {
              characterModal.classList.add('hidden');
            };
          var inputModal = document.querySelector('#input-modal');
          if (inputModal)
            inputModal.querySelector('.close-modal-button').onclick = function () {
              inputModal.classList.add('hidden');
            };

          ['confirm-modal', 'alert-modal'].forEach(function (id) {
            var modal = document.getElementById(id);
            if (modal) {
              var btn = modal.querySelector('.close-modal-button');
              if (btn)
                btn.onclick = function () {
                  modal.classList.add('hidden');
                };
            }
          });

          // --- Dynamic Data Loading and Refresh ---
          // 1. Initial Load
          runInitialization();

          // Add listener for the new settings button
          const settingsBtn = context.querySelector('.settings-btn');
          if (settingsBtn) {
            settingsBtn.addEventListener('click', openSettingsModal);
          }

          // Add listener for the new manual fill button
          const manualFillBtn = context.querySelector('#manual-fill-btn');
          if (manualFillBtn) {
            manualFillBtn.addEventListener('click', manualTableFillAndRefresh);
          }

          // Add listener for the new fullscreen button
          const fullscreenBtn = context.querySelector('#fullscreen-btn');
          if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', toggleFullScreen);
          }

          // Add listener for fullscreen changes to toggle a class
          document.addEventListener('fullscreenchange', () => {
            const interfaceElement = context; // .maho-interface
            if (document.fullscreenElement === interfaceElement) {
              interfaceElement.classList.add('fullscreen-active');
            } else {
              interfaceElement.classList.remove('fullscreen-active');
            }
          });

          // Add listener for closing the settings modal
          const settingsModal = document.querySelector('#settings-modal');
          if (settingsModal) {
            settingsModal.querySelector('.close-modal-button').addEventListener('click', () => {
              settingsModal.classList.add('hidden');
            });
          }

          // Add listener for closing the new load slots modal
          const loadSlotsModal = document.querySelector('#load-slots-modal');
          if (loadSlotsModal) {
            loadSlotsModal.querySelector('.close-modal-button').addEventListener('click', () => {
              loadSlotsModal.classList.add('hidden');
            });
          }

          // Add listeners for history navigation
          const historyNavBtn = document.getElementById('history-nav-btn');
          const historyNavPopup = document.getElementById('history-nav-popup');
          const prevSaveBtn = document.getElementById('prev-save-btn');
          const nextSaveBtn = document.getElementById('next-save-btn');

          if (historyNavBtn) {
              historyNavBtn.addEventListener('click', (e) => {
                  e.stopPropagation();
                  document.getElementById('user-input-popup').style.display = 'none'; // Hide other popups
                  historyNavPopup.style.display = historyNavPopup.style.display === 'flex' ? 'none' : 'flex';
              });
          }

          if(prevSaveBtn) {
              prevSaveBtn.addEventListener('click', () => {
                  historyNavPopup.style.display = 'none';
                  navigateHistory('previous');
              });
          }

          if(nextSaveBtn) {
              nextSaveBtn.addEventListener('click', () => {
                  historyNavPopup.style.display = 'none';
                  navigateHistory('next');
              });
          }

          // --- New User Input Button Listeners ---
          const userInputBtn = document.getElementById('user-input-btn');
          const userInputPopup = document.getElementById('user-input-popup');
          const userInputField = document.getElementById('user-input-field');
          const userInputSendBtn = document.getElementById('user-input-send-btn');

          const sendUserInput = () => {
              const text = userInputField.value;
              if (text.trim() !== '') {
                  // Per requirement, send the raw text to AI, wrapped in a request format
                  handleZeroLevelReply(`<request:{{user}}说：“${text}”>`);
                  userInputField.value = ''; // Clear after sending
                  userInputPopup.style.display = 'none'; // Hide popup after sending
              }
          };

          if (userInputBtn) {
              userInputBtn.addEventListener('click', (e) => {
                  e.stopPropagation();
                  document.getElementById('history-nav-popup').style.display = 'none'; // Hide other popups
                  const isVisible = userInputPopup.style.display === 'flex';
                  userInputPopup.style.display = isVisible ? 'none' : 'flex';
                  if (!isVisible) {
                      userInputField.focus();
                  }
              });
          }

          if (userInputSendBtn) {
              userInputSendBtn.addEventListener('click', sendUserInput);
          }

          if (userInputField) {
              userInputField.addEventListener('keydown', (e) => {
                  if (e.key === 'Enter') {
                      sendUserInput();
                  }
              });
          }

          // Hide popups when clicking outside
          document.addEventListener('click', (e) => {
              if (historyNavPopup && historyNavPopup.style.display === 'flex' && !historyNavPopup.contains(e.target) && !historyNavBtn.contains(e.target)) {
                  historyNavPopup.style.display = 'none';
              }
              const userInputPopup = document.getElementById('user-input-popup');
              if (userInputPopup && userInputPopup.style.display === 'flex' && !userInputPopup.contains(e.target) && !userInputBtn.contains(e.target)) {
                  userInputPopup.style.display = 'none';
              }
          });

          // 2. Register callback for automatic updates
          // 注册“填表完成”的回调，用于隐藏动画
          if (
            parent.AutoCardUpdaterAPI &&
            typeof parent.AutoCardUpdaterAPI.registerTableUpdateCallback === 'function'
          ) {
            parent.AutoCardUpdaterAPI.registerTableUpdateCallback(async function (newData) {
              console.log('UI received data update via callback, refreshing...');
              const uiSettings = getUiSettings();
              // If loading mode is disabled, we only refresh the UI without resetting the typewriter for both modes.
              const shouldUpdateStoryText = uiSettings.enableGalLoading;
              await refreshWithData(newData, shouldUpdateStoryText);
              // Hide Gal mode loading overlay after refresh
              const galLoadingOverlay = context.querySelector('.gal-loading-overlay');
              if (galLoadingOverlay) {
                galLoadingOverlay.style.display = 'none';
              }
            });
            console.log('Custom UI data update callback registered successfully.');
          } else {
            console.error('Failed to register UI update callback. The API might not be available.');
          }

          // [新增] 注册“填表开始”的回调，用于显示动画
          if (
            parent.AutoCardUpdaterAPI &&
            typeof parent.AutoCardUpdaterAPI.registerTableFillStartCallback === 'function'
          ) {
            parent.AutoCardUpdaterAPI.registerTableFillStartCallback(async function () {
                const uiSettings = getUiSettings();
                if (uiSettings.enableGalLoading) {
                    console.log('UI received table fill start signal, showing loading overlay...');
                    const galLoadingOverlay = context.querySelector('.gal-loading-overlay');
                    if (galLoadingOverlay) {
                        galLoadingOverlay.style.display = 'flex';
                    }
                }
            });
            console.log('Custom UI table fill start callback registered successfully.');
          } else {
            console.error('Failed to register UI update callback. The API might not be available.');
          }
        });

    /**
     * Opens the settings modal and populates it with main setting options.
     */
    async function openSettingsModal() {
        const modal = document.querySelector('#settings-modal');
        const content = modal.querySelector('#settings-modal-content');
        content.innerHTML = ''; // Clear previous buttons
        // content.style.alignItems = 'center'; // 恢复默认对齐

        const uiSettings = getUiSettings();

        // Helper function to create a setting checkbox
        const createSettingCheckbox = (key, text, initialValue, onChangeCallback) => {
            const label = document.createElement('label');
            label.style.display = 'flex';
            label.style.alignItems = 'center';
            label.style.cursor = 'pointer';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.checked = initialValue;
            checkbox.style.marginRight = '10px';
            checkbox.addEventListener('change', (event) => {
                const isChecked = event.target.checked;
                setUiSetting(key, isChecked);
                if (onChangeCallback) {
                    onChangeCallback(isChecked);
                }
            });
            label.appendChild(checkbox);
            label.appendChild(document.createTextNode(text));
            content.appendChild(label);
        };

        // --- Zero Layer/GAL Mode Toggle ---
        createSettingCheckbox('is_zero_layer_mode', '切换0层/正常gal模式', uiSettings.isZeroLayerMode);

        // --- Network Assets Checkbox ---
        createSettingCheckbox('use_network_assets', '使用网络资源库', uiSettings.useNetworkAssets, async () => {
            const freshData = parent.AutoCardUpdaterAPI.exportTableAsJson();
            await refreshWithData(freshData, true);
        });

        // --- Gal Mode Loading Animation Toggle ---
        createSettingCheckbox('enable_gal_mode_loading', '启动加载时的动画效果', uiSettings.enableGalLoading);

        // --- Typing Speed Slider ---
        const speedContainer = document.createElement('div');
        speedContainer.style.display = 'flex';
        speedContainer.style.flexDirection = 'column';
        speedContainer.style.alignItems = 'center';
        speedContainer.style.gap = '5px';
        speedContainer.style.marginTop = '10px';

        const speedLabel = document.createElement('label');
        speedLabel.textContent = '打字机速度';

        const sliderContainer = document.createElement('div');
        sliderContainer.style.display = 'flex';
        sliderContainer.style.alignItems = 'center';
        sliderContainer.style.gap = '10px';
        sliderContainer.style.width = '100%';

        const speedSlider = document.createElement('input');
        speedSlider.type = 'range';
        speedSlider.min = '0';
        speedSlider.max = '4';
        speedSlider.value = uiSettings.typingSpeed;
        speedSlider.style.flexGrow = '1';

        const speedValueLabel = document.createElement('span');
        const speedNames = ['最慢', '较慢', '正常', '较快', '瞬间'];
        speedValueLabel.textContent = speedNames[uiSettings.typingSpeed];
        speedValueLabel.style.minWidth = '40px';
        speedValueLabel.style.textAlign = 'center';

        speedSlider.addEventListener('input', (event) => {
            const speedValue = parseInt(event.target.value, 10);
            setUiSetting('typing_speed', speedValue);
            speedValueLabel.textContent = speedNames[speedValue];

            // 如果当前正在打字，则立即以新速度重新开始
            if (isTyping && currentTypingText) {
                startTypingEffect(currentTypingText);
            }
        });

        sliderContainer.appendChild(speedSlider);
        sliderContainer.appendChild(speedValueLabel);

        speedContainer.appendChild(speedLabel);
        speedContainer.appendChild(sliderContainer);
        content.appendChild(speedContainer);


        // --- Custom Default Background ---
        const backgroundButtonContainer = document.createElement('div');
        backgroundButtonContainer.style.position = 'relative'; // 为绝对定位的重置按钮提供参照
        backgroundButtonContainer.style.width = '100%';
        backgroundButtonContainer.style.textAlign = 'center'; // 内部元素默认居中

        const uploadBtn = document.createElement('button');
        uploadBtn.className = 'interaction-button';
        uploadBtn.textContent = '上传默认背景';
        uploadBtn.style.width = '150px'; // 与其他按钮保持一致的宽度
        uploadBtn.style.margin = '0 auto'; // 确保按钮本身在容器内居中
        uploadBtn.onclick = function() {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = e => {
                const file = e.target.files[0];
                if (file) {
                    const reader = new FileReader();
                    reader.onload = event => {
                        const base64String = event.target.result;
                        try {
                            localStorage.setItem('st-beautify-ui-custom-default-background', base64String);
                            showCustomAlert('自定义默认背景已更新。');
                            refreshWithData(parent.AutoCardUpdaterAPI.exportTableAsJson(), false);
                        } catch (err) {
                            showCustomAlert('图片太大无法保存到浏览器缓存，请选择一张更小的图片。');
                            console.error('Failed to save custom background:', err);
                        }
                    };
                    reader.readAsDataURL(file);
                }
            };
            input.click();
        };

        const resetBtn = document.createElement('button');
        resetBtn.className = 'interaction-button';
        resetBtn.innerHTML = '<i class="fas fa-undo"></i>';
        resetBtn.title = '重置为默认背景';
        resetBtn.style.position = 'absolute'; // 绝对定位
        resetBtn.style.right = '0'; // 定位到容器最右边
        resetBtn.style.top = '0'; // 与上传按钮顶部对齐
        resetBtn.onclick = function() {
            localStorage.removeItem('st-beautify-ui-custom-default-background');
            showCustomAlert('已重置为默认背景。');
            refreshWithData(parent.AutoCardUpdaterAPI.exportTableAsJson(), false);
        };

        backgroundButtonContainer.appendChild(uploadBtn);
        backgroundButtonContainer.appendChild(resetBtn);
        content.appendChild(backgroundButtonContainer);

        // Add a separator
        const separator = document.createElement('hr');
        separator.style.borderColor = 'rgba(100,150,200,0.2)';
        separator.style.margin = '10px 0';
        content.appendChild(separator);

        // Create the "Manual Save" button
        const manualSaveButton = document.createElement('button');
        manualSaveButton.className = 'interaction-button';
        manualSaveButton.textContent = '手动存档';
        manualSaveButton.style.width = '150px'; // 设置一个合理的固定宽度
        manualSaveButton.style.alignSelf = 'center'; // 按钮自身居中
        manualSaveButton.addEventListener('click', () => {
            modal.classList.add('hidden');
            saveStateManually();
        });
        content.appendChild(manualSaveButton);

        // Create the "Load Game" button
        const loadButton = document.createElement('button');
        loadButton.className = 'interaction-button';
        loadButton.textContent = '读取存档';
        loadButton.style.width = '150px'; // 设置一个合理的固定宽度
        loadButton.style.alignSelf = 'center'; // 按钮自身居中
        loadButton.addEventListener('click', () => {
            modal.classList.add('hidden'); // Hide current modal
            openLoadSlotsModal(); // Open the new modal with save slots
        });
        content.appendChild(loadButton);

        // Create the "Clear History" button
        const clearButton = document.createElement('button');
        clearButton.className = 'interaction-button';
        clearButton.textContent = '清空历史记录';
        clearButton.style.width = '150px'; // 设置一个合理的固定宽度
        clearButton.style.alignSelf = 'center'; // 按钮自身居中
        clearButton.addEventListener('click', () => {
            modal.classList.add('hidden'); // Hide settings modal
            clearAllHistory();
        });
        content.appendChild(clearButton);

        modal.classList.remove('hidden');
    }

        /**
         * Clears all 5 slots of story and table data from the world book.
         */
        async function clearAllHistory() {
          showCustomConfirm(
            '你确定要清空所有5个存档槽位吗？此操作会删除对应的世界书条目内容，且无法撤销。',
            async () => {
              const loadingOverlay = context.querySelector('.loading-overlay');
              try {
                if (loadingOverlay) {
                  loadingOverlay.querySelector('span').textContent = '正在清空历史记录...';
                  loadingOverlay.style.display = 'flex';
                }

                // Clear history-related data from localStorage as well
                localStorage.removeItem('st-beautify-ui-history-nav-index');
                localStorage.removeItem('st-beautify-ui-latest-save-index');

                const LOREBOOK_NAME = await TavernHelper.getCurrentCharPrimaryLorebook();
                if (!LOREBOOK_NAME) {
                  showCustomAlert('错误：未绑定主世界书，无法清空历史记录。');
                  return;
                }

                const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
                const entriesToUpdate = [];

                for (let i = 1; i <= 5; i++) {
                  const contextKey = `上下文楼层_${i}`;
                  const tableKey = `表格数据_${i}`;

                  const contextEntry = allEntries.find(e => e.comment === contextKey);
                  const tableEntry = allEntries.find(e => e.comment === tableKey);

                  if (contextEntry) {
                    entriesToUpdate.push({ uid: contextEntry.uid, content: '[已清空]' });
                  }
                  if (tableEntry) {
                    entriesToUpdate.push({ uid: tableEntry.uid, content: '{}' });
                  }
                }

                if (entriesToUpdate.length > 0) {
                  await TavernHelper.setLorebookEntries(LOREBOOK_NAME, entriesToUpdate);
                  showCustomAlert('所有存档槽位的历史记录已成功清空。');
                } else {
                  showCustomAlert('没有找到可清空的历史记录条目。');
                }
              } catch (error) {
                console.error('清空历史记录失败:', error);
                showCustomAlert(`清空历史记录时发生错误: ${error.message}`);
              } finally {
                if (loadingOverlay) {
                  loadingOverlay.style.display = 'none';
                  loadingOverlay.querySelector('span').textContent = '正在生成回复并更新数据...'; // Reset text
                }
              }
            },
          );
        }

        /**
         * Opens the modal that displays the actual load game slots.
         */
        function openLoadSlotsModal() {
          const modal = document.querySelector('#load-slots-modal');
          const content = modal.querySelector('#load-slots-content');
          content.innerHTML = ''; // Clear previous buttons

          // Add the manual load button first
          const manualLoadBtn = document.createElement('button');
          manualLoadBtn.className = 'interaction-button';
          manualLoadBtn.textContent = '读取手动存档';
          manualLoadBtn.style.backgroundColor = '#3a7f3d'; // Highlight color
          manualLoadBtn.addEventListener('click', async () => {
            modal.classList.add('hidden');
            await loadStateManually();
          });
          content.appendChild(manualLoadBtn);

          // Add a separator
          const separator = document.createElement('hr');
          separator.style.borderColor = 'rgba(100,150,200,0.2)';
          separator.style.margin = '10px 0';
          content.appendChild(separator);

          for (let i = 1; i <= 5; i++) {
            const btn = document.createElement('button');
            btn.className = 'interaction-button';
            btn.textContent = `自动存档 ${i}`; // Changed text as requested
            btn.dataset.slot = i;
            btn.addEventListener('click', async event => {
              const slot = event.currentTarget.dataset.slot;
              modal.classList.add('hidden');
              await loadStateFromLorebook(slot);
            });
            content.appendChild(btn);
          }

          modal.classList.remove('hidden');
        }

        /**
         * Navigates between world book save states.
         * @param {'previous' | 'next'} direction - The direction to navigate.
         */
        async function navigateHistory(direction) {
          const loadingOverlay = context.querySelector('.loading-overlay');
          try {
            if (loadingOverlay) {
              loadingOverlay.querySelector('span').textContent = '正在读取历史记录...';
              loadingOverlay.style.display = 'flex';
            }

            const latestSaveIndexStr = localStorage.getItem('st-beautify-ui-latest-save-index');
            if (!latestSaveIndexStr) {
              showCustomAlert('没有可用的存档记录。请先进行一次游戏以创建存档。');
              return;
            }
            const latestSaveIndex = parseInt(latestSaveIndexStr, 10);

            if (currentHistoryIndex === null) {
                    currentHistoryIndex = latestSaveIndex;
                }

                let targetIndex;

                if (direction === 'next') {
                    if (currentHistoryIndex === latestSaveIndex) {
                        showCustomAlert('已经是最新一条记录了。');
                        return;
                    }
                    targetIndex = (currentHistoryIndex % NUM_LOREBOOK_ENTRIES) + 1;
                } else { // 'previous'
                    targetIndex = ((currentHistoryIndex - 2 + NUM_LOREBOOK_ENTRIES) % NUM_LOREBOOK_ENTRIES) + 1;

                    const lorebookName = await TavernHelper.getCurrentCharPrimaryLorebook();
                    if (lorebookName) {
                        const allEntries = await TavernHelper.getLorebookEntries(lorebookName);
                        const contextKey = `上下文楼层_${targetIndex}`;
                        const targetEntry = allEntries.find(e => e.comment === contextKey);
                        if (!targetEntry || !targetEntry.content || targetEntry.content.trim() === '[已清空]' || targetEntry.content.trim() === '{}') {
                            showCustomAlert('没有更早的记录了。');
                            return;
                        }
                    } else {
                         showCustomAlert('未绑定世界书，无法读取记录。');
                         return;
                    }
                }

                await loadStateFromLorebook(targetIndex, true); // silent load
                currentHistoryIndex = targetIndex;

            } catch (error) {
                console.error('History navigation failed:', error);
                showCustomAlert(`读取历史记录失败: ${error.message}`);
            } finally {
                if (loadingOverlay) {
                    loadingOverlay.style.display = 'none';
                    loadingOverlay.querySelector('span').textContent = '正在生成回复并更新数据...';
                }
            }
        }

        /**
         * Loads game state (story text and table data) from a specified world book slot.
         * @param {number|string} slotIndex - The archive slot to load (1-5).
         * @param {boolean} silent - If true, suppresses the success alert.
         */
        async function loadStateFromLorebook(slotIndex, silent = false) {
          // When loading a specific slot, reset the history nav to this point
          currentHistoryIndex = parseInt(slotIndex, 10);
          localStorage.setItem('st-beautify-ui-history-nav-index', currentHistoryIndex);

          const LOREBOOK_NAME = await TavernHelper.getCurrentCharPrimaryLorebook();
          if (!LOREBOOK_NAME) {
            showCustomAlert('错误：未绑定主世界书，无法加载存档。');
            return;
          }

          const CONTEXT_KEY = `上下文楼层_${slotIndex}`;
          const TABLE_KEY = `表格数据_${slotIndex}`;

          try {
            const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);

            const contextEntry = allEntries.find(e => e.comment === CONTEXT_KEY);
            const tableEntry = allEntries.find(e => e.comment === TABLE_KEY);

            if (!contextEntry && !tableEntry) {
              showCustomAlert(`存档 ${slotIndex} 为空，无法加载。`);
              return;
            }

            // 1. Load table data first
            if (tableEntry && tableEntry.content) {
              // [核心修复] 使用新的导入函数，它会完全覆盖现有表格数据，确保状态一致。
              if (
                parent.AutoCardUpdaterAPI &&
                typeof parent.AutoCardUpdaterAPI.importTableAsJson === 'function'
              ) {
                parent.AutoCardUpdaterAPI.importTableAsJson(tableEntry.content);
                console.log(`已通过 "importTableAsJson" 从世界书条目 "${TABLE_KEY}" 导入表格数据。`);
              } else {
                console.error('importTableAsJson function not found on parent.');
              }
            }

            // 2. Load story text, update message, AND display with typing effect
            if (contextEntry && contextEntry.content) {
              const messages = contextEntry.content.split('\n---\n');
              const lastCharacterMessage = messages.reverse().find(m => m.startsWith('CHARACTER:'));

              if (lastCharacterMessage) {
                const rawStoryText = lastCharacterMessage.replace('CHARACTER:', '').trim();

                // First, update the underlying message data
                const chatMessages = await getChatMessages('0');
                if (chatMessages && chatMessages.length > 0) {
                  const messageZero = chatMessages[0];
                  messageZero.message = rawStoryText; // Use the raw text for the message
                  await TavernHelper.setChatMessages([messageZero], { refresh: 'none' });
                  console.log(`已将楼层 0 的消息内容覆盖为存档中的正文。`);
                } else {
                  console.error('无法获取楼层 0 的消息以进行覆盖。');
                }

                // Second, display the cleaned text with a typing effect on the UI
                const fallbackOptimizer = (text) => {
                    if (!text) return '';
                    let cleaned = text;
                    const match = text.match(/<gametext>([\s\S]*?)<\/gametext>/);
                    if (match && match[1]) cleaned = match[1];
                    return cleaned.replace(/<!--[\s\S]*?-->/g, '').replace(/<[^>]*>/g, '').trim();
                };
                const storyTextForUI = fallbackOptimizer(rawStoryText);
                startTypingEffect(storyTextForUI);
              }
            }

            // 3. Refresh UI with the newly loaded data
            // A small delay is still good practice to let backend processes catch up.
            setTimeout(() => {
              const freshData = parent.AutoCardUpdaterAPI.exportTableAsJson();
              refreshWithData(freshData, false); 
              if (!silent) {
                showCustomAlert(`存档 ${slotIndex} 加载成功！`);
              }
            }, 200);
          } catch (error) {
            console.error(`从世界书加载存档 ${slotIndex} 失败:`, error);
            showCustomAlert(`加载存档 ${slotIndex} 时发生错误: ${error.message}`);
          }
        }

        /**
         * Saves the current game state to two fixed world book entries for manual saving.
         */
        async function saveStateManually() {
          const CONTEXT_KEY = '手动存档_正文';
          const TABLE_KEY = '手动存档_表格';

          try {
            const LOREBOOK_NAME = await TavernHelper.getCurrentCharPrimaryLorebook();
            if (!LOREBOOK_NAME) {
              showCustomAlert('错误：未绑定主世界书，无法手动存档。');
              return;
            }

            const lorebooks = await TavernHelper.getLorebooks();
            if (!lorebooks.includes(LOREBOOK_NAME)) {
              showCustomAlert(`错误：角色卡指定的世界书 "${LOREBOOK_NAME}" 未找到。`);
              return;
            }

            const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
            let contextEntry = allEntries.find(entry => entry.comment === CONTEXT_KEY);
            let tableEntry = allEntries.find(entry => entry.comment === TABLE_KEY);

            const createOrUpdateEntry = async (key, content, existingEntry) => {
              const entryType = 'selective'; // Manual saves should also be selective
              if (!existingEntry) {
                const newEntryData = {
                  comment: key,
                  keys: [key],
                  content: content,
                  enabled: true,
                  type: entryType,
                  position: 'after_char',
                  order: 3000,
                };
                await TavernHelper.createLorebookEntries(LOREBOOK_NAME, [newEntryData]);
              } else {
                await TavernHelper.setLorebookEntries(LOREBOOK_NAME, [
                  { uid: existingEntry.uid, content: content, enabled: true, type: entryType },
                ]);
              }
            };

            // 1. Save current story text (last AI reply)
            const allMessages = await getChatMessages(getCurrentMessageId());
            const lastMessage = allMessages[allMessages.length - 1];
            const contextContent = lastMessage.is_user ? '' : `CHARACTER: ${lastMessage.message}`;

            if (!contextContent) {
              showCustomAlert('没有找到可供保存的AI回复内容。');
              return;
            }

            await createOrUpdateEntry(CONTEXT_KEY, contextContent, contextEntry);

            // 2. Save current table data
            const tableDataJson = parent.AutoCardUpdaterAPI.exportTableAsJson();
            const tableContent = JSON.stringify(tableDataJson, null, 2);
            await createOrUpdateEntry(TABLE_KEY, tableContent, tableEntry);

            showCustomAlert('手动存档成功！');
          } catch (error) {
            console.error('手动存档失败:', error);
            showCustomAlert(`手动存档时发生错误: ${error.message}`);
          }
        }

        /**
         * Toggles fullscreen mode for the entire page.
         */
        function toggleFullScreen() {
          const interfaceElement = context; // .maho-interface
          if (!document.fullscreenElement) {
            interfaceElement.requestFullscreen().catch(err => {
              showCustomAlert(`进入全屏模式失败: ${err.message}`);
            });
          } else {
            if (document.exitFullscreen) {
              document.exitFullscreen();
            }
          }
        }

        /**
         * Loads the game state from the fixed manual save entries.
         */
        async function loadStateManually() {
          currentHistoryIndex = null;
          localStorage.removeItem('st-beautify-ui-history-nav-index');

          const LOREBOOK_NAME = await TavernHelper.getCurrentCharPrimaryLorebook();
          if (!LOREBOOK_NAME) {
            showCustomAlert('错误：未绑定主世界书，无法加载手动存档。');
            return;
          }

          const CONTEXT_KEY = '手动存档_正文';
          const TABLE_KEY = '手动存档_表格';

          try {
            const allEntries = await TavernHelper.getLorebookEntries(LOREBOOK_NAME);
            const contextEntry = allEntries.find(e => e.comment === CONTEXT_KEY);
            const tableEntry = allEntries.find(e => e.comment === TABLE_KEY);

            if (!contextEntry && !tableEntry) {
              showCustomAlert('手动存档为空，无法加载。');
              return;
            }

            if (tableEntry && tableEntry.content) {
              parent.AutoCardUpdaterAPI.importTableAsJson(tableEntry.content);
            }

            if (contextEntry && contextEntry.content) {
              const lastCharacterMessage = contextEntry.content;
              if (lastCharacterMessage.startsWith('CHARACTER:')) {
                const rawStoryText = lastCharacterMessage.replace('CHARACTER:', '').trim();
                const chatMessages = await getChatMessages('0');
                if (chatMessages && chatMessages.length > 0) {
                  chatMessages[0].message = rawStoryText;
                  await TavernHelper.setChatMessages(chatMessages, { refresh: 'none' });
                }
                const storyTextForUI = extractStoryText(rawStoryText);
                startTypingEffect(storyTextForUI);
              }
            }

            setTimeout(() => {
              const freshData = parent.AutoCardUpdaterAPI.exportTableAsJson();
              refreshWithData(freshData, false);
              showCustomAlert('手动存档加载成功！');
            }, 200);
          } catch (error) {
            console.error('加载手动存档失败:', error);
            showCustomAlert(`加载手动存档时发生错误: ${error.message}`);
          }
        }
      })();
    </script>
  </body>
</html>

